quests[40562] = { id = 40562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Note", description = "Schön, Euch wiederzusehen, {name}. Es muss ewig her sein, als wir das letzte Mal miteinander sprachen.\n\nWir haben Informationen über eine Gruppe in der Juwelierskunst bewanderter Nachtgeborener in Suramar erhalten, die unglaubliche Dinge mit Halsketten vollbringen. Ich würde mir gerne einige ihrer Edelsteine ansehen.\n\nUnd ihre Vorlagen.\n\nUnd... eine Lupe wäre auch toll. Ich hörte, dass die Stadtinspektoren welche haben.", sourceObjective = "Beschafft eine Lupe der Nachtgeborenen, eine individuelle Schmuckbestellung und 5 Schmuckkästchen der Nachtgeborenen.", progress = "Oh, wie ich von den Edelsteinen der Nachtgeborenen erfahren habe? Nun, das ist ein Betriebsgeheimnis.\n\n<Sminx blinzelt Euch zu.>", completion = "Die Elfen machen doch immer die qualitativ hochwertigsten Dinge. Ich behalte diese Edelsteine, wenn es Euch nichts ausmacht.\n\nDiese Juwelierskunstvorlage, andererseits... Ein {class}, der der Juwelierskunst mächtig wäre, könnte doch sicher etwas damit anfangen, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[40564] = { id = 40564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shoe Shine Kit Tracking Quest" }
quests[40565] = { id = 40565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkles Wispern" }
quests[40567] = { id = 40567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Den Alptraum betreten", description = "Wir konnten Ysera nicht retten, aber wir haben sie davon abgehalten, den Tempel zu zerstören.\n\nNun kann ich mich endlich meinem Ehemann widmen.\n\nIch weiß nicht, welches Schicksal er gerade erleidet. Ich weiß nur, dass Ihr sofort gehen müsst, wenn wir überhaupt eine Chance haben wollen, ihn zu retten.\n\nFolgt Xavius in den Alptraum und findet Malfurion.\n\nBitte rettet meinen Ehemann, wenn Ihr könnt.", sourceObjective = "Begebt Euch in das Finsterherzdickicht und tötet den Schemen von Xavius.", completion = "Lobet Elune und all das, was ihr Licht berührt... Malfurion lebt.\n\nIch dachte schon, ich müsse den Rest meiner Tage alleine verbringen und davon träumen, welche anderen Entscheidungen ich hätte treffen können.\n\nIch danke Euch. Danke, dass Ihr mir meinen Liebsten zurückgebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40568] = { id = 40568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zorn des Sturms", description = "Die Teufelsskorn, die sich über meine Brut hermachen, gehörten einst zu den Drekirjar, einem Stamm, mit dem wir einen uralten Pakt geschlossen hatten. Unter dem Einfluss des Gottkönigs vergessen sie nun ihren Eid und greifen die Vorfahren ihrer geliebten Drachen an.\n\nFür diesen Affront müssen sie büßen.\n\nErweckt Euren Zorn und tragt den Kampf zu ihnen, {class}!", sourceObjective = "Tötet 10 Teufelsskornvrykul am Thorimshorn.", progress = "Sind wir die Teufelsskorn los?", completion = "Heute haben die Teufelsskorn erfahren, was wahre Stärke bedeutet.\n\nSie werden es sich zweimal überlegen, noch einmal die Klingen gegen Euch zu erheben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40569] = { id = 40569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende der Sande", description = "Nichts! Es steht praktisch nichts über diese Waffe in unseren Aufzeichnungen!\n\nIch habe sie immer wieder durchgesehen, aber es ist fast nichts über ihre Geschichte bekannt. Das heißt, dass die Geschichte nur außerhalb von Pandaria stattgefunden haben kann.\n\nLi Li Sturmbräu ist zwar noch jung, aber neben Euch ist sie die Meistgereiste der ganzen Insel. Wenn jemand etwas über diese Waffe weiß, dann sie.", sourceObjective = "Sprecht mit Li Li Sturmbräu.", progress = "Was ist los?", completion = "Glaubt Ihr, dass diese Geschichte wahr ist? Ich wette, Ihr könnt die Macht dieser Klingen beherrschen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40570] = { id = 40570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmelwärts", description = "Dieser Stein ist durchdrungen von elementarer Kraft, möglicherweise Reste der Magie, die gegen Irmaat zum Einsatz kam!\n\nWenn Ihr nach draußen geht und diesen Stein in die Luft haltet, solltet Ihr dadurch die Essenz des Steins als mächtigen Wirbelwind entfesseln können. Und der Wirbelwind sollte stark genug sein, um Euch und Euren Gefährten bis zum Himmelswall zu tragen!\n\nWenn die Handklingen von Irmaat, die Fäuste der Himmel, immer noch so mächtig sind wie in den alten Geschichten, dann werden sie sich dort befinden.", sourceObjective = "Bergt die Fäuste der Himmel.", completion = "Was für eine großartige Unternehmung, {name}! Das sollten wir öfter machen!\n\nDa Ihr jetzt diese Klingen habt, warten wohl jede Menge Abenteuer auf Euch!\n\nIch sollte vielleicht einfach eine Weile hierbleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40571] = { id = 40571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finsterherzdickicht - Belohnungsquest für heroischen Dungeon" }
quests[40572] = { id = 40572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finsterherzdickicht - Belohnungsquest für normalen Dungeon" }
quests[40573] = { id = 40573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Alptraumfürst", description = "Ihr seid gerade noch rechtzeitig gekommen, <mein Freund/meine Liebe>.\n\nKagraxxis hätte mich jeden Moment seinem Meister geopfert... Ich hatte schon mit meinem Leben abgeschlossen.\n\nIch bin Euch sehr dankbar, aber wir sind immer noch in Gefahr... Xavius ist zurückgekehrt.\n\nDer Alptraumfürst ist hier in Val'sharah und koordiniert höchstpersönlich die Verderbnis des Landes. Das hat mir mein Peiniger offenbart, kurz bevor er mich schächten wollte.\n\nWir müssen Thaon Mondklaue finden und ihm davon berichten, bevor es zu spät ist!", sourceObjective = "Berichtet Thaon Mondklaue von Xavius' Rückkehr.", completion = "Thaon Mondklaue war ein großer Druide und ein wahrer Beschützer dieses Landes.\n\nWie können wir ohne ihn an unserer Seite darauf hoffen, den Alptraumfürsten zu besiegen?", sourceObjectiveStatus = "unverified-source-field" }
quests[40574] = { id = 40574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golganneth Shrine Cleansed" }
quests[40578] = { id = 40578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respekt erweisen", description = "Alles, was ich sehe, ist Verzweiflung.\n\nSchaut selbst, {race}. Das Gelände ist voller zorniger Geister derjenigen, die hier begraben liegen. Irgendjemand hat sie erzürnt und jetzt schlagen sie um sich. Ich kann ihren Schmerz spüren.\n\nIch werde nach verbliebenen Relikten Ausschau halten und ein ganz bestimmtes Grabmal aufsuchen. Für diese armen Seelen ist es zu spät. Bitte vernichtet so viele von ihnen, wie Ihr könnt, damit sie wieder ihre verdiente Ruhe finden.", sourceObjective = "Vernichtet 8 verstörte Erscheinungen oder verstörte Schreckgespenster.", completion = "Es tut mir weh, sie so leiden zu sehen. Sie werden wiederkommen, aber zunächst einmal haben sie Ruhe gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40579] = { id = 40579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Waffen", description = "Als <größter Krieger/größte Kriegerin> in diesen Hallen braucht Ihr eine angemessen mächtige Waffe, um Euren und meinen Willen durchzusetzen. Ich habe meinen Blick auf Azeroth gerichtet und ein paar Artefakte gefunden, die Euer würdig wären.\n\nIch überlasse Euch die Wahl, nach welchem Artefakt Ihr suchen möchtet, um die Legion zu bekämpfen. Später werden wir dann die anderen sichern.", sourceObjective = "Wählt eine Artefaktwaffe aus, nach der Ihr suchen wollt.", completion = "Ich wusste, dass dies Eure Wahl sein würde. Nutzt sie also weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[40580] = { id = 40580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protection Chosen" }
