quests[40583] = { id = 40583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut - Choice UI - Deadly Deep Amber" }
quests[40584] = { id = 40584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Witnessed Drake Lift Crystal" }
quests[40585] = { id = 40585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und der Krieg beginnt", description = "Die Legion denkt, dass Ihr tot seid. Sie werden einigermaßen überrascht sein, wenn Ihr sie für diese Fehleinschätzung straft!\n\nHiermit können wir das gesamte Gebiet der Verheerten Inseln überblicken und den Kriegern verschiedene Aufgaben zuweisen.\n\nWenn Ihr einen Blick darauf geworfen habt, solltet Ihr das erste Operationsgebiet auswählen. Ich habe schon mal die besten Angriffspunkte zusammengestellt!", sourceObjective = "Wählt den ersten Angriffspunkt Eures Ordens.", completion = "Eine ausgezeichnete Wahl, {name}. Ich werde Euch darauf hinweisen, wenn sich weitere günstige Gelegenheiten ergeben sollten. Viel Glück in der Schlacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[40586] = { id = 40586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut - Choice UI - Quick Azsunite" }
quests[40587] = { id = 40587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making the Cut - Choice UI - Masterful Queen's Opal" }
quests[40588] = { id = 40588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren des Fluchs", description = "Nun gut. Dann also der Reihe nach: Ich bin Revil Kost, ein Priester des Lichts auf der Suche nach verschollenen Artefakten. Ich habe schon einmal mit den Dunklen Reitern zu tun gehabt und bin zurückgekehrt, um diesen Ort von ihnen zu befreien.\n\nDie Reiter sind nicht leicht zu fassen, aber ich weiß vielleicht, wo wir einen Hinweis auf sie finden können. In einem unserer früheren Kämpfe konnte ich einen Blick auf ihre Vergangenheit erhaschen. Dank des Segens, den mir der Umhang der Reinheit gewährte, sah ich, wer die Dunklen Reiter früher waren.\n\nKommt mit mir in Aridens Lager. Ich werde Euch auf dem Weg alles erklären.", sourceObjective = "Begleitet Revil Kost vom Anwesen der Dunstmantels im Dämmerwald zu Aridens Lager am Gebirgspass der Totenwinde.", completion = "Es ist seltsam, dass die Dunklen Reiter uns nicht hierher gefolgt sind. Aber ich nehme jeden Vorteil, den ich kriegen kann.\n\nIch glaube, dass hier irgendwo der Schlüssel zum Aufenthaltsort der Dunklen Reiter verborgen liegt. Lasst uns mit der Suche beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40591] = { id = 40591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Second Valarjar", description = "Whatever your feelings towards him, he is still one of the finests warriors on Azeroth. He has led battles from the front, advised Warchiefs, and mixes excellent martial prowess with tactical calm. You can trust his judgment as well as his axe. Speak with him yourself.Ihr erlernt:" }
quests[40593] = { id = 40593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen unter uns", description = "Der König ist weise, sich auf die Bedrohung durch die Legion zu konzentrieren, {name}. Schon jetzt sind die Dämonen gegen uns mobilisiert.\n\nDie Illidari werden die Allianz unterstützen. Wir glauben, dass sie es auf bedeutende Standorte in Azeroth abgesehen haben. Sie könnten sogar schon unter Euch lauern!\n\nIch spüre ihre Nähe...", sourceObjective = "Beschützt Burg Sturmwind vor der Legion.", progress = "Ich hätte nie geglaubt, dass sie in meinen eigenen Thronsaal gedrungen wären! Dem Licht sei Dank, dass Ihr da wart!", completion = "Dieser Angriff... selbst die Schlacht an der Verheerten Küste... sie sind nur der Anfang des Feldzugs der Legion.\n\nWenn wir keinen Weg finden, um sie aufzuhalten, werden wir alles verlieren, was mein Vater und die anderen Anführer für uns aufgebaut haben.\n\nDie Stärke der Illidari muss hinter uns stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40594] = { id = 40594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerechtigkeit von oben", description = "Tötet jetzt, trauert später!\n\nHier, Champion. Fliegt auf einem meiner Kriegsadler und nutzt die Kräfte, die Euch unsere vereinten Stämme gewährt haben, um Vernichtung auf die Drogbar herabregnen zu lassen.\n\nStopfen wir den neuen Eingang zu ihrem Hort mit ihren eigenen Leichen!", sourceObjective = "Bombardiert die Streitkräfte des Tiefgesteinsrisses.", progress = "Die Drogbar scheinen diese Felsen wirklich zu mögen.", completion = "Gut gemacht. Auch aus Euch machen wir noch ein Himmelshorn.", sourceObjectiveStatus = "unverified-source-field" }
quests[40598] = { id = 40598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschliff - Auswahl-UI - Himmelssteinring" }
quests[40599] = { id = 40599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschliff - Auswahl-UI - Tiefenbernsteinring" }
quests[40600] = { id = 40600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinschliff - Auswahl-UI - Azsunitring" }
quests[40601] = { id = 40601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Pinerock Basin - Highmountain Beastmaster See Treasure (JLW)" }
quests[40603] = { id = 40603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach den Valkyra", description = "So eine Katastrophe können wir nicht noch einmal riskieren. Wir müssen das Herz gegen die Teufelsenergie schützen, bevor wir unsere Arbeit fortsetzen.\n\nDie mächtige Ashildir hat sich willens gezeigt, jenen zu helfen, die sich ihr als würdig erwiesen haben, und ihr Meister kann uns vielleicht helfen, das Herz zu beschützen.\n\nGeht zu ihr. Sie befindet sich in der Kammer von Eyir in Sturmheim. Ich treffe Euch dann dort.", sourceObjective = "Sucht Ashildir in der Kammer von Eyir in Sturmheim auf.", completion = "Sagt nichts. Ich weiß, wonach Ihr sucht.\n\nGlaubt Ihr, dass Ihr bereit seid für die Prüfungen, die vor Euch liegen?", sourceObjectiveStatus = "unverified-source-field" }
quests[40604] = { id = 40604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberührte Zeugen", description = "Hier hatte der Händler Ariden sein Lager aufgeschlagen, als er einst versuchte, seine dubiosen Waren dem Zauberer Medivh zu verkaufen. Seltsamerweise ist es über all diese Zeit hinweg relativ unberührt geblieben. Deswegen glaube ich, dass immer noch eine Verbindung zum vormaligen Besitzer bestehen könnte.\n\nHelft mir, das Lager zu durchsuchen. Vielleicht finden wir hier etwas, das uns zu den Dunklen Reitern führt.", sourceObjective = "Sucht Aridens Lager nach Hinweisen auf den Aufenthaltsort der Dunklen Reiter ab.", completion = "Dieses eigentlich ganz gewöhnlich aussehende Tagebuch brummt vor dunkler Energie, während Ihr Euch nähert.\n\nEin kurzer Blick auf die Texte offenbart, dass dies Aridens Tagebuch ist, das von seiner Zeit im Gebirgspass der Totenwinde handelt. Am Ende des Buches ändert sich der Schreibstil und der Unterton wird zunehmend düsterer. Ab hier dreht sich alles um einen \"Fluch\" und das endlose Begehren nach Dingen von großer Macht.\n\nEiner dieser Einträge fällt Euch besonders ins Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[40605] = { id = 40605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet Eure Freunde nahe bei Euch", description = "Die Legion ist wirklich sehr verwegen, sich auf die Hordenfestung zu stürzen! Ihr habt uns bei der Verteidigung wirklich geholfen, doch ich habe eine noch wichtigere Aufgabe für Euch.\n\nAnscheinend werden die Dämonenjäger eine wichtige Rolle im kommenden Krieg übernehmen... doch ich vertraue ihnen immer noch nicht. Ihr werdet mein Abgesandter bei den Illidari sein. Findet heraus, was sie wissen. Erlernt ihre Techniken. Falls sie uns verraten, werden wir ihr eigenes Wissen gegen sie einsetzen.\n\nIhr Lager befindet sich auf dem Plateau inmitten der Stadt. Geht nun. Nathanos und ich werden uns um das Chaos hier kümmern.", sourceObjective = "Sprecht mit Elthyn Da'rai im Lager der Illidari auf dem Plateau in Orgrimmar.", completion = "Ah, Ihr seid also der gerühmte {class}, von dem ich gehört habe. Gut.\n\nMal sehen, ob Ihr Eurem Ruf gerecht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40606] = { id = 40606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wegweiser", description = "Obwohl das Tagebuch größtenteils düsteres, hastig hingekritzeltes Geschreibsel beinhaltet, sticht ein Eintrag heraus:\n\n\"Ulthalesh. Dieser Name durchdringt meinen Verstand. Er ruft nach mir, aber von woher?\n\nDie Geister... Das ganze Land hier ist daran gebunden. Es ist kein Wunder, dass wir uns so oft verirren. Diese Kräfte lassen meine Kompassnadel in alle möglichen Richtungen schwingen...\n\nVielleicht könnte der Kompass den Weg weisen, wenn die Anziehungskraft größer wäre...\"", sourceObjective = "Sucht nach dem Kompass, der in dem Tagebuch erwähnt wird, das Ihr in Aridens Lager gefunden habt.", progress = "Ist er das?", completion = "Mit diesem Kompass stimmt ganz eindeutig etwas nicht.\n\nEr scheint in alle Richtungen gleichzeitig zeigen zu wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40607] = { id = 40607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonen unter uns", description = "Blickt Euch um. Was seht Ihr?\n\n<Allari starrt über Eure Schulter hinweg.>\n\nDie Legion hat die Horde bereits unterwandert... Sie sind hier.\n\nWir müssen Euren Kriegshäuptling beschützen.\n\nSagt Bescheid, wenn Ihr bereit seid, zu erfahren, was hinter dem Schleier wartet.", sourceObjective = "Findet heraus, was Allari die Seelenfresserin sieht.", progress = "Die Illidari hatten recht! Vernichtet die Dämonen, {name}!", completion = "Anscheinend waren die Bedenken der Dämonenjäger durchaus begründet. Kaum zu fassen, dass Dämonen es wagen würden, sich in dieser Zeit der Trauer in unsere Stadt zu schleusen!\n\nDas ist kein gutes Zeichen für den Rest meines Königreichs.", sourceObjectiveStatus = "unverified-source-field" }
quests[40608] = { id = 40608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Mal", description = "Eure Klinge ist bereits sehr mächtig, aber sie hat noch nicht ihr volles Potential entfaltet. Der unermesslich mächtige Odyn in den Hallen der Tapferkeit kann Euch seine Stärke verleihen.\n\nUm diesen Segen zu erbitten, müsst Ihr ihm allerdings eine angemessene Gabe zukommen lassen. Ich weiß, wo Ihr so etwas finden könnt, aber dafür benötigt Ihr zunächst einmal das Mal der Valkyra.\n\nIhr müsst Euch als unseres Mals würdig erweisen, Champion, dann dürft Ihr in die Kammer von Eyir eintreten. Dort wird die Göttin Eure weiteren Schritte lenken.", sourceObjective = "Besteht die Prüfung der Valarjar, um das Mal der Valkyra von Eyir zu erhalten.", progress = "Ich grüße Euch, Champion. Wie verläuft die Prüfung?", completion = "<Ashildir nickt wissend.>\n\nIhr seid bereit für den nächsten Schritt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40609] = { id = 40609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Windripper Peak - Taurson - Tracking Quest Credit - See Treasure (JLW/RKS)" }
quests[40610] = { id = 40610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Worm Treasure - Tracking Quest Credit - See Treasure (JLW/RKS)" }
quests[40611] = { id = 40611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Totenwinde", description = "In dem Tagebuch steht etwas von \"größerer Anziehungskraft\" für den Kompass. Wenn die Geister dieses Ortes wirklich daran gebunden sind, könnten sie ja vielleicht für diese Anziehungskraft sorgen.\n\nIch habe am Pass verschiedene Stellen mit ruhelosen Geistern entdeckt. Möglicherweise können sie uns ja die richtige Richtung weisen, wenn Ihr ihnen den Kompass zeigt.\n\nBegebt Ihr Euch an diese Orte. Ich reise weiter nach Karazhan und versuche, noch mehr über die Dunklen Reiter herauszufinden.", sourceObjective = "Kalibriert Aridens Kompass mithilfe der ruhelosen Geister am Gebirgspass der Totenwinde.", completion = "Es scheint funktioniert zu haben. Der Kompass zeigt in Richtung des Flusses.\n\nKönnte es sein, dass...?", sourceObjectiveStatus = "unverified-source-field" }
quests[40612] = { id = 40612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Vignette - Amateur Hunters - Tracking Quest Credit - See Treasure (JAP)" }
quests[40613] = { id = 40613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: Die Rettung des Svalngards", description = "Einst war der Svalngard Odyns Schild. Es wird behauptet, dass er die Hallen der Tapferkeit vor der endlosen Dunkelheit unter seinem Reich geschützt hat.\n\nHelya, die vor langer Zeit aus den glänzenden Hallen vertrieben wurde, stahl den Svalngard und verbarg ihn in ihrem verfluchten Schiff, der Naglfar.\n\nIhr müsst Euch an Bord der Naglfar begeben und Helya besiegen, um den Svalngard wiederzubeschaffen. Er wird einen würdigen Tribut für Odyn abgeben.", sourceObjective = "Beschafft den Svalngard und besiegt Helya im Seelenschlund auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Konntet Ihr den Svalngard Helyas Klauen entreißen?", completion = "Es bleibt noch eine Aufgabe, bevor Ihr zu den Hallen reist, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40614] = { id = 40614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fürstliches Festmahl für Odyn", description = "In den Hallen der Tapferkeit ist es guter Brauch, das Ende eines Kampfes mit einem Festmahl zu begehen. Wenn Ihr Odyn ein glorreiches Festmahl aus Wildtierfleisch kredenzt, das seines Thrones würdig ist, zeigt Ihr die richtige Entschlossenheit, um seinen Segen zu erhalten.\n\nBesorgt Lendenstücke vom Donnerhorn in Sturmheim, die Wirbelsäule des Wirbelschnitters vom Hochberg und das feine Steak des Leyhauers aus Azsuna. Ein solches Festmahl wäre eine würdige Vorbereitung auf die gewaltige Schlacht, die uns bevorsteht.", sourceObjective = "Besorgt ein Lendenstück vom Donnerhorn in Sturmheim, die Wirbelsäule des Wirbelschnitters vom Hochberg und das Steak des Leyhauers aus Azsuna.", progress = "Die Bestien, die ihr jagt, haben vielen das Leben genommen.", completion = "Meine Wachen werden das Festmahl vorbereiten. Wir dagegen müssen Eure Reise zu den Hallen besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40615] = { id = 40615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Odyns Segen", description = "Ihr seid bereit, {class}.\n\nReist zu Odyns strahlenden Hallen und opfert das Festmahl auf dem Altar darin. Odyn wird dann seinen Blick auf Euch richten. Ihr müsst die uralten Prüfungen der Valarjar unter seinen wachsamen Augen bestehen.\n\nErst dann werdet Ihr Odyns Segen erhalten.", sourceObjective = "Erhaltet Odyns Segen in den Hallen der Tapferkeit auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Nur wenige haben Odyns Segen begehrt und sind triumphierend zurückgekehrt.", completion = "Ich kann Odyns Macht von hier aus spüren. Die Magie der Legion wird Euch nicht länger aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40616] = { id = 40616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - W1 - Saw Leader Die" }
quests[40617] = { id = 40617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Nachtauge offen halten", description = "<Fremder/Fremde>, Ihr müsst mir helfen!\n\nNachtauge, mein alter Freund... Er ging als Späher voraus und plötzlich hörte ich, wie er einen Warnruf ausstieß. Ich versuchte, ihm nachzulaufen, aber durch meine Unvorsichtigkeit bin ich in seine Falle gestolpert.\n\nEr ist ganz in der Nähe auf der anderen Seite dieses Bergkamms. Bitte findet ihn!", sourceObjective = "Helft Lilryia Morgenwind dabei, Nachtauge zu finden.", progress = "Ihr müsst Nachtauge finden!", completion = "Ich danke Euch, {race}. Ich werde Nachtauges Wunden versorgen. Erzählt mir, was passiert ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[40618] = { id = 40618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Waffen", description = "Drei Waffen... drei verdienstvolle Pfade.\n\nUm den Kampf gegen die Legion in die Wege zu leiten, müsst Ihr zunächst in den Besitz eines solchen Artefakts gelangen. Die Waffe wird im Laufe ihrer Verwendung zunehmend mächtiger. Ihr müsst also diejenige auswählen, auf die Ihr Eure Anstrengungen konzentrieren möchtet, {name}.\n\nNach einer Weile werdet Ihr Euch auch die anderen Waffen aneignen können. Aber jetzt müsst Ihr Euch entscheiden, nach welcher davon Ihr zuerst suchen wollt.", sourceObjective = "Wählt die erste Artefaktwaffe aus, nach der Ihr suchen wollt.", completion = "Jetzt müsst Ihr mit der Suche nach dem Artefakt beginnen. Dies wird keine leichte Aufgabe werden, doch eine Waffe mit solcher Macht ist selten leicht zu haben.\n\nKommt zu mir zurück, wenn Eure Suche erfolgreich war. Dann werden wir diese Sache weiter besprechen. Es gibt noch viel für uns zu tun!", sourceObjectiveStatus = "unverified-source-field" }
quests[40619] = { id = 40619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survival Chosen" }
quests[40620] = { id = 40620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marksman Chosen" }
quests[40621] = { id = 40621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beast Mastery Chosen" }
quests[40622] = { id = 40622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aman'thul Shrine Cleansed" }
quests[40623] = { id = 40623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunklen Reiter", description = "Am Flussufer findet sich ein Kanalisationsgitter, über das man in die Tunnel gelangen kann, die unterhalb von Karazhan verlaufen. Ich habe es nie beachtet, aber vielleicht ist das der Ort, an den die Geister uns führen wollen.\n\nVielleicht haben sich die Dunklen Reiter ja die ganze Zeit direkt unter unseren Füßen aufgehalten! Kommt, lasst uns schauen, wo uns das hinführt.", sourceObjective = "Besiegt die Dunklen Reiter in den Katakomben von Karazhan und nehmt Ulthalesh an Euch.", completion = "Heute haben wir den Dunklen Reitern einen schweren Schlag versetzt und einen Sieg für die Bewohner des Dämmerwalds errungen.\n\nSie stehen genauso in Eurer Schuld wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[40625] = { id = 40625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine neue Quelle", description = "Ihr müsst mir etwas besorgen.\n\nIch glaube, ich stehe kurz davor, eine neue Magiequelle zu entdecken, brauche aber bestimmte Werkzeuge.\n\nIch kann nicht länger in meine Werkstatt am Stadtrand, aber ich habe gesehen, wie die kleineren Dämonen in der Tiefe Werkzeuge verwenden. Bringt mir eins ihrer Werkzeuge und ich kann unsere Leute retten.", sourceObjective = "Findet einen Teufelsdekonstruktor für Kyrtos.", progress = "Habt Ihr etwas gefunden? Ich hatte nun mal keine Zeit, meine Siebensachen zu packen, bevor ich verbannt wurde.", completion = "Mehr habt Ihr nicht gefunden? Ich nehme an, es wird reichen müssen, obwohl das ein primitives Werkzeug ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[40627] = { id = 40627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Odyn Event Complete" }
quests[40628] = { id = 40628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Ashbringer" }
quests[40629] = { id = 40629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Ashbringer" }
quests[40630] = { id = 40630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattered Ashbringer" }
quests[40631] = { id = 40631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Glanz des Ruhmes", description = "Der Segen des großen Odyn selbst, er... er strahlt aus Euch hervor!\n\nIhr müsst sofort zu Euren Leuten zurückkehren. Odyns Licht ist ein Geschenk, an dem alle teilhaben müssen.", sourceObjective = "Kehrt zu Schwester Elda im Sanktum des Lichts zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[40632] = { id = 40632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt mich zu Eurem Anführer", description = "Ich bin sehr froh, dass Ihr da seid, {name}.\n\nDieser... Khadgar, der Erzmagier, der meine Nachricht gefunden hat, hat ein Treffen einberufen.\n\nEr möchte uns so schnell wie möglich am Eingang zur Stadt treffen.\n\nWürdet Ihr mich begleiten? Ich habe so eine Ahnung, dass er nicht allein sein wird.", sourceObjective = "Trefft Euch mit Khadgar in Suramar.", completion = "Da seid Ihr ja, Champion. Nun sind wir also vollzählig.", sourceObjectiveStatus = "unverified-source-field" }
quests[40633] = { id = 40633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ins Abenteuer!", description = "Oh, ich würde zu gern herausfinden, ob die Geschichte wahr ist! Aber Papa ist viel zu beschäftigt damit, sich den Bauch vollzuschlagen und ein Griesgram zu sein, um mich ein paar echte Erkundungen machen zu lassen. Er hat mir sogar gesagt, ich dürfe ohne Geleitschutz nicht das Dorf verlassen!\n\nWas fällt ihm eigentlich ein? Ich kann sehr gut auf mich selbst aufpassen!\n\nAber vielleicht wollt Ihr mir ja Geleitschutz geben? Bitte helft mir, dieser Langeweile hier zu entkommen!", sourceObjective = "Sprecht mit Li Li in Ramkahen.", completion = "He da, {name}. Wo wart Ihr so lange?\n\nWährend Ihr auf Reisen wart, habe ich ein bisschen Forschung betrieben. König Phaoris hat uns seine Hilfe angeboten, wenn wir uns um ein Problem für ihn kümmern.\n\nIch bin mir sicher, dass Ihr ihm dabei helfen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40634] = { id = 40634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Donner über dem Sand", description = "Ich kenne die Geschichte von Irmaat sehr gut. Es heißt, sein Zuhause sei die uralte Stadt Ahmtul gewesen, die seit Langem unter dem Wüstensand begraben liegt.\n\nVor Kurzem gab es einen seltsamen Sturm über den Ruinen. Und ich höre, dass ein Elementar namens Nader meine Leute in den nahe gelegenen Ländern angreift.\n\nDa muss es einen Zusammenhang geben.\n\nSucht nach diesem Nader und schaltet ihn aus. Und durchsucht seine Überreste nach einem Hinweis auf die Ursache dieser Vorkommnisse.", sourceObjective = "Besiegt Nader und durchsucht seinen Leichnam nach einem Hinweis.", progress = "Habt Ihr schon etwas gefunden, {name}?", completion = "Dieser Stein befand sich also unter seinen Überresten?\n\nInteressant. Lasst mich mal sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40635] = { id = 40635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlächter der Sashj'tar", description = "Ich kann nicht fassen, dass Throndyr nicht mehr unter uns weilt.\n\nIch schwöre bei meinen Hörnern, dass wir uns für all das rächen werden, was die Sashj'tar uns angetan haben!\n\nKämpft weiter, {name}. Tötet sie! Tötet sie alle!", sourceObjective = "Tötet 12 Naga der Sashj'tar im Azurwindmeerbogen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40636] = { id = 40636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereiten zum Angriff", description = "Die Brennende Legion hat uns am Gipfel der Ruhe überrascht. Wir werden nicht zulassen, dass dies noch einmal geschieht!\n\nWir haben eine harte Ausbildung durchlaufen, aber wenn wir dieses große Übel vernichten wollen, benötigen wir leistungsfähige Waffen.\n\nIn unseren Schriftrollen werden ein paar Waffen mit entsprechender Macht erwähnt. Aber wir wissen nicht, welche davon wir zuerst suchen sollen.\n\nWir überlassen diese Wahl daher Euch, <Großmeister/Großmeisterin>.", sourceObjective = "Wählt eine Artefaktwaffe, nach der Ihr suchen wollt.", completion = "Wie Ihr wünscht, Großmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[40637] = { id = 40637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Ehre", description = "<Brandolf atmet schwer.>\n\nDiese Höhle wird meine letzte Ruhestätte, {name}.\n\nSucht Toryl. Sagt ihr, was hier heute geschehen ist.\n\nLasst ganz Jandvik wissen, dass ich gestorben bin, um unser Dorf zu verteidigen...", sourceObjective = "Kehrt zu Toryl in Jandvik zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[40638] = { id = 40638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windwalker Chosen" }
quests[40639] = { id = 40639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mistweaver Chosen" }
quests[40640] = { id = 40640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brewmaster Chosen" }
quests[40642] = { id = 40642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht! Her mit der Macht!", description = "Ich brauche mehr Energie! Ich brauche mehr!\n\nIch kann die Energien kontrollieren und sie reichen aus, um mich zu nähren. Zumindest vorerst.\n\nIch werde nicht verdorren und wie diese anderen Schwächlinge enden.\n\nZieht los zur Teufelsseelenbastion und tötet die Dämonen dort. Beeilt Euch und bringt mir ihre Essenzen!", sourceObjective = "Sammelt 8 Teufelsessenzen für Kyrtos.", progress = "Habt Ihr die Essenzen? Gebt her!", completion = "<Kyrtos verzehrt gierig die Essenzen.>\n\nAh, schon viel besser! Jetzt kann ich mich auf die Forschung konzentrieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[40643] = { id = 40643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einbestellt zur Mondlichtung", description = "Eure umgehende Anwesenheit auf der Mondlichtung wird erbeten, {name}.\n\nWir bereiten ein äußerst wichtiges Ritual vor und benötigen Eure Unterstützung.\n\nIch werde Euch dort erwarten, also eilt Euch bitte!", sourceObjective = "Trefft Hamuul Runentotem auf der Mondlichtung.\n\nBereitgestellter Gegenstand:", completion = "{name}! Ich bin froh, dass Ihr so kurzfristig kommen konntet.\n\nWir nehmen hier auf der Mondlichtung gerade ein großes Unterfangen in Angriff, bei dem Ihr eine Schlüsselrolle spielen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40644] = { id = 40644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Traumpfad", description = "Die Vorbereitungen für das Ritual sind jetzt abgeschlossen.\n\nKommt, {name}, ich werde Euch jetzt zur Zeremonie geleiten.", sourceObjective = "Helft bei der Durchführung des Rituals.", completion = "Gut gemacht, {name}!\n\nJetzt ist der Weg offen. Unsere Reise nach Val'sharah kann beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40645] = { id = 40645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Hain der Träume", description = "Das Portal zum Traumpfad steht offen und hier werden sich jetzt unsere Wege trennen. Die Mondlichtung ist weiterhin anfällig für die Angriffe der Brennenden Legion und ich muss dafür sorgen, dass sie gut geschützt wird.\n\nIch vertraue Euch die Mission in Val'sharah an, {name}. Erzdruide Großhuf ist der dortige Anführer der Druiden. Er verfügt über uralte Weisheit und wird uns eine große Hilfe sein.\n\nDer Traum kann gefährlich sein, weswegen ich Bewahrer Remulos anweisen werde, Euch zu begleiten. Ihr trefft ihn auf der anderen Seite.", sourceObjective = "Geht durch das Portal zum Hain der Träume.", completion = "Es war eine beachtliche Leistung von Euch, den Weg durch den Smaragdgrünen Traum hierher zu finden. Aber manchmal möchtet Ihr diese Strecke vielleicht schneller zurücklegen. Dieser Zauber wird Euch leiten.\n\nDen Traumpfad zu beschreiten, ist nicht einfach, aber die vor Euch liegenden Aufgaben sind ungleich schwerer.", sourceObjectiveStatus = "unverified-source-field" }
quests[40646] = { id = 40646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendäre Waffen", description = "Ich stimme mit Bewahrer Remulos überein. Um die Legion bekämpfen und besiegen zu können, benötigen wir Waffen mit legendären Kräften.\n\nIn der Geschichte der Druiden fanden vier solcher Waffen besondere Erwähnung.\n\nAlso sagt mir, nach welcher Waffe wollt Ihr zuerst suchen?", sourceObjective = "Wählt eine Artefaktwaffe aus, nach der Ihr suchen wollt.", completion = "Eine sehr weise Wahl, {name}!\n\nMit der Macht einer solchen Waffe in Euren Händen können wir das Gleichgewicht auf Azeroth wiederherstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40647] = { id = 40647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn Träume zu Alpträumen werden", description = "Mit Ursols Segen können wir jetzt sicher die magischen Zauberschutze passieren und die Klauen erreichen!\n\nDazu müssen wir uns in den Traum hineinbegeben. Wenn Ihr Euch vor den Schrein von Ursol legt und vom Mondwasser trinkt, das Ihr mitgebracht habt, wird Euer Geist in den Traum eintauchen.\n\nAber gebt auf Euch acht, denn der Traum kann ein gefährlicher Ort sein.", sourceObjective = "Begebt Euch in den Smaragdgrünen Traum, um Ursocs Klauen zu beschaffen.", progress = "Habt Ihr Ursocs Klauen an Euch bringen können?", completion = "Ich verdanke Euch mein Leben, {name}. Ohne Euer Eingreifen hätte ich den Tod oder noch Schlimmeres gefunden.\n\nDieser Verräter Xavius hat uns vielleicht Ursoc genommen, aber zumindest konnten wir die Klauen sichern. Es gibt also noch Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[40649] = { id = 40649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft Mylune", description = "Es fügt sich, dass Ihr gerade jetzt auf der Suche nach G'Hanir seid, {name}. Die Dryade Mylune ist vor Kurzem vom heiligen Schrein zurückgekehrt, wo der Stab seit Jahrhunderten bewacht wird.\n\nNur wenige wissen um das Versteck in den Wurzeln von Shaladrassil, aber Ihr verdient es zweifellos, in dieses Geheimnis eingeweiht zu werden.\n\nSprecht mit Mylune, wenn Ihr bereit zum Aufbruch seid. Zuletzt habe ich sie östlich von hier auf dem Hügel gesehen.", sourceObjective = "Sucht Mylune auf.", completion = "<Mylune hat Tauwasser in den Augen und statt eines Lächelns zeigt sie ein sorgenvolles Gesicht.>\n\nJa...?", sourceObjectiveStatus = "unverified-source-field" }
quests[40650] = { id = 40650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Zen'tabra", sourceObjective = "Ich bin schon 'ne ganze Weile am Grübeln, {name}. Meinen Wanderstab hab ich vor langer Zeit zugunsten eines friedvoll'n Lebens beiseitegelegt. Wollte an meinem Lebensabend eigentlich nur noch Druidenkünste lehr'n.\n\nDoch jetzt will der Krieg meine Heimat in Stücke reiß'n und dabei kann ich nich' einfach zuseh'n.\n\nMein Stab und ich sind bereit für 'ne neue Reise an Eurer Seite, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40651] = { id = 40651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Saat der Zeitalter", description = "Diese Waffen wurden mithilfe uralter Magie erschaffen. Die wahre Macht Eures Artefakts liegt in seiner Fähigkeit, immer stärker zu werden, je mehr Ihr es verwendet.\n\nNachdem Ihr Eure Waffe nun auf die Saat der Zeitalter eingestimmt habt, könnt Ihr mithilfe ihrer Magie zusätzliche Attribute für Eure Waffe freischalten.\n\nVerwendet sie jetzt, um das Potenzial Eurer Waffe zu entfalten.", sourceObjective = "Verleiht Eurer Waffe zusätzliche Macht, indem Ihr einen Artefaktpunkt zuweist.", completion = "Ausgezeichnet!\n\nWenn Eure Waffe an Macht gewinnt, könnt Ihr hierher zurückkehren und ihr wahres Potenzial entfesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[40652] = { id = 40652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Himmlische Informationen", description = "Es ist an der Zeit, dass wir uns der Situation auf den Verheerten Inseln zuwenden.\n\nHimmelsfürst Omnuron hat Informationen über alle Vorgänge auf den Inseln zusammengetragen. Wenn sich eine günstige Gelegenheit bieten sollte, die Legion anzugreifen, wird er davon wissen.\n\nSucht ihn auf und hört Euch an, was er zu berichten hat.", sourceObjective = "Sprecht mit Himmelsfürst Omnuron.", completion = "Ich grüße Euch, Erzdruide.\n\nWir sehen uns mit zahlreichen Bedrohungen konfrontiert. Wir müssen umgehend handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[40653] = { id = 40653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren legen", description = "Die Brennende Legion bedroht die physische Existenz von Azeroth, aber der Alptraum hat es auf die Seele unserer Welt selbst abgesehen. Wir müssen beide Bedrohungen ausschalten, wenn wir überleben wollen.\n\nMithilfe dieser Karte können wir alle Entwicklungen auf den Verheerten Inseln nachvollziehen und zeitnah auf Bedrohungen reagieren. Aufgrund der begrenzten Anzahl unserer Truppen sollten wir sie zunächst da einsetzen, wo sie am meisten ausrichten können.\n\nNehmt selbst die Lage in Augenschein und entscheidet dann, wo wir beginnen sollen.", sourceObjective = "Wählt das erste Operationsgebiet Eures Ordens aus.", completion = "Ja, da stimme ich Euch zu. Auf diesen Ort sollten wir unsere ersten Bemühungen konzentrieren.\n\nIch werde Euch darauf hinweisen, wenn sich neue Bedrohungen ergeben sollten. Möge Elune Euch den Weg weisen, Erzdruide.", sourceObjectiveStatus = "unverified-source-field" }
quests[40654] = { id = 40654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druiden der Klaue", description = "Ein neuer Verbündeter hat sich uns angeschlossen. Sein Name ist Yaris Dunkelklaue und er ist ein erfahrener Ausbilder der Druiden der Klaue.\n\nGeht und sprecht jetzt mit ihm.", sourceObjective = "Sprecht mit Yaris Dunkelklaue.", completion = "Ausgezeichnet. Sehr bald werden die Druiden der Klaue unsere Reihen verstärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[40655] = { id = 40655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li" }
quests[40657] = { id = 40657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelstechnik", description = "Ein erster Schritt zum Verständnis von Magie liegt darin, Materialien zu analysieren und zu verstehen, die mit dieser Magie erschaffen wurden. So bin ich immerhin zu meinem Durchbruch mit den Seelenkristallen der Hexenmeister gelangt.\n\nDie Wyrmzungendiener in dieser Grube hämmern Platten in ihre Bauten, um sie abzustützen und zu reparieren. Die wären ein guter Anfang. Besorgt mir ein paar davon, <mein treuer Gehilfe/meine treue Gehilfin>!", sourceObjective = "Sammelt 10 teufelsgeladene Platten für Kyrtos.", progress = "Ich kann geradezu spüren, wie Macht durch die Gebäude strömt.", completion = "Hervorragend. Indem ich diese Materialien untersuche, kann ich besser nachvollziehen, wie sie ihre Maschinen und Architektur mit Magie durchwirken.", sourceObjectiveStatus = "unverified-source-field" }
quests[40658] = { id = 40658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - W1 - See Demon Attack" }
quests[40659] = { id = 40659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternchen sehen", description = "Ihr glaubt, diese Naga sind eine nette Herausforderung, kleines Häschen?\n\n<Stokalfr kichert.>\n\nIch würde einiges dafür geben, mit einem dieser muschelbewachsenen Monstren kämpfen zu können.\n\nWenn Ihr bei mir Eindruck schinden wollt, dann bringt mir die Sterne, die sie auf ihren Köpfen tragen. Dann nehme ich Euch womöglich ab, dass Ihr <ein wahrer/eine wahre:c> {class} seid.", sourceObjective = "Beschafft 4 Seesterne von alten Grubengängern in der Azurwindbucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40661] = { id = 40661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schutz der heimischen Front", description = "Die Legion ist nicht nur in diese Stadt gedrungen. Das von ihr ausgehende Böse verbreitet sich über ganz Azeroth und bedroht die äußersten Randbereiche unserer Welt.\n\nWir müssen sie finden und aufhalten, wo auch immer ihre Dunkelheit Fuß fasst.\n\nWir haben Späher ausgesandt, die sich auf der ganzen Welt nach Legionsaktivität umsehen. Sobald Invasionen starten, werden wir die Standorte auf Eurer Karte markieren.\n\nLasst sie leiden, {name}!", sourceObjective = "Öffnet Eure Karte, um aktive Legionsinvasionen in Kalimdor oder den Östlichen Königreichen zu finden. Geht zum Invasionsort und haltet die Dämonen auf!", progress = "Findet sie! Haltet sie auf! Geleidet Euch wohl.", completion = "Ihr habt es geschafft! Ihr habt eine Invasion gebrochen!\n\nWenn das nur das Ende unseres Kampfes wäre. Doch die Legion gibt erst nach, wenn sie vernichtet wurde... oder uns vernichtet hat.\n\nGebt nicht auf! Schlagt mehr dieser elenden Invasionen zurück, {name}. Die Wyrmzunge, die wir hier gefangen halten, wird Eure Bemühungen entlohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40662] = { id = 40662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattered Chosen" }
quests[40663] = { id = 40663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiery Chosen" }
quests[40664] = { id = 40664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Corrupted Chosen" }
quests[40668] = { id = 40668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Das Herz von Zin-Azshari", description = "Die Naga im Auge Azsharas beschwören schreckliche Stürme herauf, die die Küste von Azsuna verheeren. Selbst ihre fähigsten Sirenen wären dazu nicht imstande.\n\nEs kann nur das Herz von Zin-Azshari sein.\n\nVor der Zerschlagung nutzten Azsharas Auserwählte das Herz, um ihre Kräfte massiv zu verstärken. Es heißt, es soll der Schlüssel zu ihrer Vorherrschaft am Brunnen der Ewigkeit sein.\n\nWenn Ihr zu ihnen reist und das Herz für uns besorgt, {name}, werden wir seine Kräfte besser zu nutzen wissen als diese verkommenen Kreaturen.", sourceObjective = "Besorgt das Herz von Zin-Azshari und besiegt Azsharas Zorn im Auge Azsharas auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Habt Ihr das Herz besorgt?", completion = "Es bedarf sehr großer Anstrengungen, die zerstörerischen Energien in den Tiefen des Herzens richtig zu verfeinern, aber Ihr werdet es schon schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40672] = { id = 40672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: Das Auge isst mit", description = "Odyn verlangt ein Festmahl, das den uralten Prüfungen, die vor Euch liegen, angemessen ist. Es kommt nicht nur darauf an, wie viele große Wildtiere darin angehäuft sind, sondern auch darauf, worauf sie serviert werden.\n\nTief unter dem Hochberg befindet sich der frühere Hort von Neltharion. Ihr kennt den Höllenfeuerdrachen vielleicht besser als Todesschwinge. Dort in den tiefsten Nischen werdet Ihr die Überreste der Adamantiumpanzerung finden, die seine geschmolzene Haut zusammengehalten hat.\n\nSie werden ausgezeichnete Servierplatten für das Festmahl abgeben.", sourceObjective = "Besorgt 4 Teile Adamantiumplattenschrott und besiegt Dargrul den Unterkönig in Neltharions Hort auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Wagt es nicht, Odyn ein Festmahl ohne angemessene Servierplatten darzubieten. Das würde nur seinen Grimm heraufbeschwören.", completion = "Sie werden würdige Servierplatten abgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40673] = { id = 40673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorenes Wissen", description = "Wir sind tatsächlich mit der Magie der Nachtgeborenen vertraut, aber wir erhalten keinen Zugang zum Herz. Das ist nur den Günstlingen der Königin vorbehalten.\n\nTrotzdem wissen wir, wie man seine Magie richtig anzapft.\n\nVor Jahrtausenden studierte ein Gelehrter der Nachtgeborenen das Herz und zeichnete seine Erkenntnisse überaus sorgfältig auf. Er wurde hingerichtet und die Schriftrolle mit seinen Aufzeichnungen verbannt, aber die Nachtsüchtigen konnten sie auf ihrer Flucht heimlich entwenden.\n\nWenn Ihr die Schriftrolle besorgt, werden wir Euch helfen können.", sourceObjective = "Beschafft die Schriftrolle von Elun'dris von der Ersten Arkanistin Thalyssra.", progress = "Seit dem Verrat der Nachtgeborenen sind die Nachtsüchtigen recht... misstrauisch... geworden. Sie lassen Euch erst in die Nähe der Schriftrolle, wenn Ihr Euch ihren Respekt verdient habt.", completion = "<Aufmerksam liest Thalrenus die Schriftrolle.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40674] = { id = 40674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wundersames Wasser", description = "Als wir uns das letzte Mal begegnet sind, war ich in einem Käfig, {race}. Ihr habt bereits einmal Euer Leben für meinesgleichen riskiert. Seid Ihr bereit, mir ein weiteres Mal zu helfen?\n\nViele von uns wurden beim Angriff der Schlangen verletzt. Ich benötige heilendes Wasser für meine Heilrituale.\n\nIch habe beobachtet, wie die Schlangen dieses Wasser verwenden. Bringt es mir, wenn Ihr welches findet.", sourceObjective = "Besorgt 6 Krüge mit heilendem Wasser aus den Ruinen der Sashj'tar.", sourceObjectiveStatus = "unverified-source-field" }
quests[40675] = { id = 40675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arkus: Das Ritual des Hauptmanns", description = "Nur ein Hauptmann der Wache kann die Macht unseres Ordens empfangen. So schreiben es unsere uralten Gesetze vor.\n\nIhr müsst das Ritual des Hauptmanns abschließen.\n\nDer Tradition nach patrouillieren die Anwärter drei Wochen lang ohne Ruhepause durch den Arkus, wobei das große Labyrinth ihre Fähigkeiten als Wache auf die Probe stellt. Unsere Gesetze müssen befolgt werden, aber ich glaube, dass Ihr Euch auch anders beweisen könnt.\n\nElisandes Berater, Vandros, hat sich vor Kurzem in die Tiefen des Arkus begeben. Tötet ihn und nehmt seinen Weltenzeitwinder an Euch.", sourceObjective = "Nehmt den Weltenzeitwinder von Berater Vandros im Arkus auf dem Schwierigkeitsgrad 'Mythisch' an Euch.", progress = "Habt Ihr das Ritual wie gefordert beendet?", completion = "Gut gemacht. Der Weltenzeitwinder wird uns helfen, die empfindliche Magie innerhalb des Herzens zu kontrollieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[40676] = { id = 40676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit drängt", description = "Ich schlage vor, dass Ihr unverzüglich aufbrecht, {name}. Ihr seid schon viel zu lange hier gewesen. Die Meuchelmörder der Legion könnten jeden Moment auftauchen und versuchen, Euch umzubringen.\n\nPasst gut auf, wenn Ihr das Herz verwendet. Trotz der Bindungen, die Euch die Handhabung ermöglichen, ist die ihm innewohnende Macht gefährlich.", sourceObjective = "Kehrt zu König Magni Bronzebart in den Hügeln unterhalb von Eisenschmiede zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[40678] = { id = 40678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdrehte Macht", description = "Es ist Zeit, unsere Arbeit einem Test zu unterziehen. Wir werden die stärkste mir bekannte Energiequelle, die Teufelsenergie, anreichern.\n\nIn sehr seltenen Fällen tragen die Diener der Legion Bruchstücke großer Portalsteine bei sich, um damit ihre Eredarmeister herbeizurufen. Wenn Ihr genug sammeln könnt, um einen vollständigen Stein daraus zu formen, könnt Ihr ihn am Altar der Endzeit in Faronaar benutzen, um den Eredarfürsten Vizuul den Verwachsenen herbeizurufen.\n\nDie Bindungen, die Vizuul zur Verstärkung seiner Macht bei sich trägt, sollten das Herz bis an seine Grenzen bringen.", sourceObjective = "Verwendet einen großen Portalstein, um Vizuul den Verwachsenen am Altar der Endzeit in Faronaar herbeizurufen, und nehmt ihm dann seine Runenbindungen ab.", progress = "Habt Ihr die Bindungen?", completion = "Jetzt lasst uns sehen, was passiert, wenn wir das Herz benutzen, um ihnen ihre Macht zu entziehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40680] = { id = 40680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Vignette: Rok'nash - twh" }
quests[40681] = { id = 40681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snarf" }
quests[40683] = { id = 40683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Entdeckungen ohne Experimente", description = "Ich kann überall an Euch Magierückstände wahrnehmen. Ihr werdet Euch als nützlich erweisen.\n\nIch muss untersuchen, wie die Körper der Dämonen Teufelsenergie in so hohen Mengen aushalten können. Ich habe reichlich Proben ihres Fleisches, doch es gibt sicher noch etwas Besseres...\n\nHolt mir einige Rückgrate der Basilisken in der Nähe, damit ich deren magische Rückstände analysieren kann. Es wäre schließlich sinnlos, wenn wir uns beide die Hände schmutzig machen, nicht wahr?", sourceObjective = "Sammelt 8 Teufelsfeuerrückgrate von Teufelsfeuerbasilisken.", progress = "Ich hoffe, Ihr habt mir genug mitgebracht. Ich brauche mehr Energie, bevor ich meine Untersuchungen abschließen kann.", completion = "Teufelsmagie ist irgendwie... seltsam. Geradezu glitschig, wie eine Art Öl, und sie brennt lange und heiß. Vielleicht gibt es da einen Zusammenhang...", sourceObjectiveStatus = "unverified-source-field" }
quests[40684] = { id = 40684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der verseuchten Instrumente", description = "Dieses Buch ist der Schlüssel zur Rettung Eurer Freunde und zu Eurer absoluten Macht! Es enthält Informationen über viele gefährliche Relikte, die keinesfalls der Legion in die Hände fallen dürfen.\n\nLest es, <Freund/Freundin>, und entscheidet, welches Artefakt Ihr im Kampf gegen Jagganoth verwenden wollt!", sourceObjective = "Sprecht mit Calydus, um zu entscheiden, nach welchem Artefakt Ihr suchen wollt.", progress = "Habt Ihr Eure Wahl getroffen?", completion = "Weise gewählt, Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[40686] = { id = 40686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Affliction Chosen" }
