quests[40692] = { id = 40692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Suramar - Treasure 000 - The Drift - L (DLA)" }
quests[40693] = { id = 40693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Nashal - Auswahl-UI - Tödliches Auge der Prophezeiung" }
quests[40694] = { id = 40694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kleiner Schritt für die Magie", description = "Es ist an der Zeit, die Zukunft willkommen zu heißen.\n\nIch habe alle uns bekannten Arten der Magie gemeistert. Ich werde es auch mit dieser hier schaffen.\n\nWenn man die Prinzipien von Arkanmagie anwendet, ist es ein Leichtes, die primitiven Teufelsenergien in dem von Euch besorgten Material zu beherrschen. Ich muss mich als Nächstes an einem Lebendobjekt versuchen.\n\nBeginnen wir mit einer kleinen Beschwörung. Besiegt die Kreatur für mich und seht dann zu, wie ein wahrer Gelehrter vorgeht.", sourceObjective = "Sprecht mit Kyrtos und helft ihm bei seinem Ritual.", progress = "Ah, was für eine faszinierende Beobachtung.", completion = "Ja...\n\nDiese Macht ist... andersartig. Roh, ungestüm und stark.\n\nIch kann sie beherrschen. Ich kann sie meistern!", sourceObjectiveStatus = "unverified-source-field" }
quests[40695] = { id = 40695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Nashal - Auswahl-UI - Spiegelndes Morgenlicht" }
quests[40696] = { id = 40696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Augen von Nashal - Auswahl-UI - Meisterlicher Schattenrubin" }
quests[40698] = { id = 40698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinheit der Form", description = "<Meister/Meisterin>, wir haben eine neue Technik entdeckt, die es jemandem mit großen Fokusfähigkeiten ermöglicht, das Chi im Innern magischer Objekte auszuformen. Mithilfe dieser Technik könnt Ihr die Fähigkeiten Eurer neuen Waffe erheblich verbessern.\n\nFür diese Technik wird sehr viel Fokus benötigt, deswegen müssen wir uns zunächst auf eine einzige Verbesserung beschränken. Aber das wird reichen müssen.", sourceObjective = "Verwendet die Schmiede des tosenden Bergs, um Euer Artefakt mit einer neuen Kraft zu verstärken.", progress = "Erstaunlich!", completion = "Diese Waffe ist wirklich erstaunlich. Aber ein großer Teil ihres Potenzials ist immer noch ungenutzt.\n\nWenn wir die Brennende Legion ein für alle Mal besiegen wollen, müssen wir ihre volle Kraft entfesseln.", sourceObjectiveStatus = "unverified-source-field" }
quests[40699] = { id = 40699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Credit - Scenario Complete" }
quests[40701] = { id = 40701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feral Chosen" }
quests[40702] = { id = 40702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guardian Chosen" }
quests[40703] = { id = 40703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restoration Chosen" }
quests[40704] = { id = 40704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Li Li Sturmbräu", sourceObjective = "Wisst Ihr, ich hab gerade daran gedacht, wie viel Spaß wir schon zusammen hatten. Ich bin gern mit Euch gemeinsam unterwegs und ich bin mir sicher, dass Onkel Chen auch nichts dagegen hätte, weil Ihr ja ein Großmeister seid und so.\n\nDamit möchte ich sagen, dass ich sehr gern Eure Kundschafterin, Späherin oder hiesige Abenteurerin sein würde. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[40705] = { id = 40705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Priesterangelegenheiten", description = "<Meister/Meisterin> {name}, ich komme im Auftrag von jemandem, der sich anschickt, einen stärkeren Widerstand gegen die Legion zu organisieren.\n\nEr bittet Euch, zu Faols Ruheplatz in Tirisfal zu kommen. Er garantiert für Eure Sicherheit und stellt Euch eine größere Rolle in diesem Konflikt in Aussicht.", sourceObjective = "Nehmt am geheimen Treffen an Faols Ruheplatz in Tirisfal teil.", completion = "Dann seid Ihr also einverstanden?\n\nWenn Ihr bereit seid, würde ich gern sofort beginnen.\n\nIch weiß um Eure enormen Fähigkeiten, aber dennoch dürfen wir nichts dem Zufall überlassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40706] = { id = 40706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legenden zum Anfassen", description = "Damit Ihr Euch den bevorstehenden Prüfungen unterziehen könnt, benötigt Ihr eine Waffe zur Verstärkung Eurer beträchtlichen Fähigkeiten. Ich habe einige Möglichkeiten in Erfahrung gebracht, die Ihr in Betracht ziehen solltet.\n\nIhr müsst entscheiden, nach welcher Waffe Ihr zuerst suchen wollt. Ich habe größtes Vertrauen in Eure Wahl.", sourceObjective = "Wählt eine Artefaktwaffe aus, nach der Ihr suchen wollt.", completion = "Eine weise Entscheidung. Meine Ordensbrüder und ich werden Euch bei Euren nächsten Schritten unterstützen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40707] = { id = 40707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Chosen" }
quests[40708] = { id = 40708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Chosen" }
quests[40709] = { id = 40709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discipline Chosen" }
quests[40710] = { id = 40710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klinge des Schattenhammers", description = "Ich habe zusammen mit Moira Thaurissan darauf hingearbeitet, den Schattenhammer zu infiltrieren. Dabei haben wir von einem mächtigen Artefakt der Alten Götter erfahren, einem Schwert, das zu verschiedenen Zeitpunkten der Geschichte verwendet wurde, um für Angst und Schrecken zu sorgen.\n\nMoiras Doppelagent berichtet, dass es einen möglichen neuen Anführer gibt, der seine Machtergreifung mithilfe dieser Waffe und eines unheiligen Rituals untermauern will. Ihr müsst ihn finden, das Ritual unterbinden und das Artefakt an Euch nehmen.\n\nWir treffen uns danach in Dalaran.", sourceObjective = "Unterbindet das Ritual und nehmt Xal'atath, die Klinge des Schwarzen Imperiums, an Euch.", completion = "Ihr habt ein beachtliches Talent für diese Art von Aufgaben an den Tag gelegt.\n\nDas ist erfreulich, denn wir werden Euch noch mehr abverlangen müssen, wenn wir diesen Konflikt überleben wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40711] = { id = 40711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 019 - [Ley Line Tower]" }
quests[40712] = { id = 40712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die einstige Macht", description = "Ich habe mich in Euch getäuscht, <Hexenmeister/Hexenmeisterin>. Durch Eure Hilfe im Kampf gegen die Dunklen Reiter habt Ihr dem Licht Ehre erwiesen. Vielleicht sollte ich weniger vorschnell urteilen.\n\nAuf jeden Fall konnte ich dank Eurer Hilfe die Artefakte ihren rechtmäßigen Besitzern zurückgeben. Und ich denke, dass Ulthalesh bei Euch in den denkbar besten Händen ist.\n\nMöge es Euch im Kampf gegen die Legion gute Dienste erweisen, <Hexenmeister/Hexenmeisterin>.", sourceObjective = "Kehrt zu Calydus in der Schattenseite von Dalaran zurück.", completion = "Freund hat Waffe?\n\nJa, Calydus kann ihre Macht spüren!", sourceObjectiveStatus = "unverified-source-field" }
quests[40713] = { id = 40713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwarze Foliant", description = "Ich habe eine bedeutende Entdeckung gemacht, {name}.\n\nIn der Seelenmaschine befindet sich ein mächtiger Hexenmeister, der einen ebenso mächtigen Folianten besitzt. Er enthält verbotene Geheimnisse, mithilfe derer die stärksten Dämonen beschworen werden können.\n\nSelbst die Legion scheut davor zurück, diese Teufelslords zu rufen, doch nun besitze ich Wissen, das das ihre weit übersteigt.\n\nHolt mir diesen Folianten, dann wird es mir nie wieder an Magie mangeln.", sourceObjective = "Beschafft den schwarzen Folianten.", progress = "Der Foliant! Habt Ihr ihn?", completion = "Wahrhaftig... Diese Seiten enthalten das Geheimnis, diese Macht wirklich zu meistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[40714] = { id = 40714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Krieg", description = "<Ein eisiger Gedanke durchweht Euren Verstand.>\n\nHört mich an, {name}.\n\nDie Legion ist zurückgekehrt. Sie hoffen darauf, uns zu beherrschen und unseren Willen zu beugen. Doch sie sind nur Narren, die unsere Klingen zu spüren bekommen werden.\n\nEure Brüder und Schwestern in Dalaran sammeln sich zur Stunde an Krasus' Landeplatz. Begebt Euch dorthin und sucht Herzog Lankral auf. Er wird Euch alles erklären.", sourceObjective = "Trefft Euch mit Herzog Lankral an Krasus' Landeplatz.", completion = "Ihr habt sicherlich viele Fragen, aber die müssen jetzt erst einmal warten. Wir befinden uns bereits im Krieg!\n\nWir müssen uns beeilen, aber ich werde versuchen, Euch die Situation in aller Kürze zu erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[40715] = { id = 40715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein erforderliches Bündnis", description = "In diesem Krieg haben wir einen unerwarteten Verbündeten an unserer Seite, {name}. Um die Brennende Legion zu besiegen, können wir jede Hilfe gebrauchen.\n\nDie Schwarze Klinge wird dem Lichkönig als verlängerter Arm dienen, solange die Geißel in Nordend gebunden ist. Im Gegenzug für unsere Hilfe hat unser Verbündeter angeboten, bei der Beschaffung mächtiger Waffen für die stärksten unserer Ritter zu helfen. Waffen, die so mächtig sind, dass sie das endgültige Ende der Legion bedeuten könnten!\n\nIhr zählt zu unseren besten Kriegern, {name}. Ich möchte, dass Ihr selbst entscheidet, nach welcher Waffe Ihr suchen wollt.", sourceObjective = "Wählt eine Artefaktwaffe, nach der Ihr suchen wollt.", completion = "Eine ausgezeichnete Wahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[40716] = { id = 40716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sechs", description = "Seid gegrüßt, <Hexenmeister/Hexenmeisterin>. Ich spreche im Namen des Rats der Schwarzen Ernte.\n\nDie Angriffe der Legion haben uns schmerzvoll verdeutlicht, dass unsere einzige Hoffnung darin liegt, stärker zu werden. Der Rat plant, sich dem Wirbelnden Nether zuzuwenden, um neue, mächtige Dämonenverbündete zu gewinnen. Das Ritual kann eigentlich beginnen, wir sind aber eine Person zu wenig.\n\nZweifellos habt Ihr von Kanrethad Schwarzhaupts Schicksal gehört?\n\nWir möchten, dass Ihr ihn ersetzt. Nehmt Ihr an?", sourceObjective = "Trefft Euch mit Ritssyn Flammengroll im Kreis der Mächte unterhalb von Dalaran.", completion = "Das war die richtige Entscheidung.\n\nWollen wir hoffen, dass Ihr Eurem Ruf gerecht werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40717] = { id = 40717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Rates", description = "<Die Arkananomalie wendet sich Euch zu und spricht Euch mit Khadgars unverwechselbarer Stimme an.>\n\nObwohl ich Euren Kampf gegen die Legion nur äußerst ungern unterbreche, muss ich Euch in einer... diplomatischen Angelegenheit um Hilfe bitten. Wir sehen uns einer schweren Bedrohung gegenüber und um sie zu überstehen, müssen wir unsere gesamte Stärke aufbieten.\n\nNicht jeder wird mit diesem Standpunkt einverstanden sein.\n\nBitte sucht mich vor der Violetten Zitadelle in Dalaran auf. Wir haben die Stadt neu positioniert, um die Östlichen Königreiche zu verteidigen. Sie befindet sich über dem Gebirgspass der Totenwinde oberhalb von Karazhan.", sourceObjective = "Sucht Khadgar in Dalaran am neuen Standort oberhalb des Gebirgspasses der Totenwinde auf.", completion = "Jainas Reaktion war bedauerlich, aber nicht unerwartet. Sie hat so viel durchgemacht...\n\nObwohl es Garrosh Höllschrei war, der die Vernichtung von Theramore befohlen hat, gibt sie der ganzen Horde die Schuld für ihren Verlust. Ich hoffe, dass sie diesen Hass eines Tages überwinden kann.\n\nAber genug der Grübelei. Wir müssen die Kirin Tor auf den Krieg vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40718] = { id = 40718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Rates", description = "<Die Arkananomalie spricht Euch mit Khadgars Stimme an.>\n\nObwohl ich Euren Kampf gegen die Legion nur äußerst ungern unterbreche, muss ich Euch in einer... diplomatischen Angelegenheit um Hilfe bitten. Wir sehen uns einer schweren Bedrohung gegenüber und um sie zu überstehen, brauchen wir die Stärke aller Völker Azeroths.\n\nDie Horde muss wieder ein Teil der Kirin Tor werden. Nicht jeder wird mit diesem Standpunkt einverstanden sein.\n\nBitte sucht mich vor der Violetten Zitadelle in Dalaran auf. Wir haben die Stadt oberhalb von Karazhan neu positioniert, um die Östlichen Königreiche zu verteidigen.", sourceObjective = "Sucht Khadgar in Dalaran am neuen Standort oberhalb des Gebirgspasses der Totenwinde auf.", completion = "Jainas Reaktion war bedauerlich, aber nicht unerwartet. Sie hat so viel durchgemacht...\n\nObwohl es Garrosh Höllschrei war, der die Vernichtung von Theramore befohlen hat, kann sie bei Eurem Anblick – oder dem irgendeines Mitglieds der Horde – immer nur an ihr Verlangen nach Rache denken. Ich hoffe, dass sie diesen Hass eines Tages überwinden kann.\n\nAber genug der Grübelei. Wir müssen die Kirin Tor auf den Krieg vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40719] = { id = 40719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEPRECATE- REUSE" }
