quests[40722] = { id = 40722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Chosen" }
quests[40723] = { id = 40723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frost Chosen" }
quests[40724] = { id = 40724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Chosen" }
quests[40725] = { id = 40725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arganax", description = "Ein als Arganax bekannter Satyr hat sich in das Dorf Lorlathil in Val'sharah eingeschlichen. Ich bin überzeugt, dass Arganax sich als Bewohner des Dorfes verkleidet hat.\n\nWendet das dämonische Auge von Azzorok auf die Bewohner in Lorlathil an. Falls sich ein Dämon unter ihnen verbirgt, wird das Auge von Azzorok seine wahre Identität aufdecken.\n\nSpürt den dämonischen Eindringling Arganax auf und und zeigt ihm keine Gnade.", sourceObjective = "Sucht nach Arganax in Lorlathil und tötet ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[40727] = { id = 40727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachablösung", description = "In letzter Zeit habe ich einige neugierige Blicke bemerkt.\n\nIch liefere ja gerne weiterhin Waren an Vanthir, doch die Arbeit wird immer gefährlicher.\n\nDie Dämmerwache am Basar ist besonders aufmerksam.\n\nSucht die Orbitisten und tötet sie, damit ich meine Waren wieder sicher ausliefern kann.\n\nIch folge Euch mit der Lieferung.", sourceObjective = "Tötet 3 Orbitisten der Dämmerwache.", completion = "Dank Euch konnte Deline die Waren sicher ausliefern.", sourceObjectiveStatus = "unverified-source-field" }
quests[40728] = { id = 40728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wormgut's Quest" }
quests[40729] = { id = 40729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frisches Blut", description = "Es ist Zeit, mit dem Ritual zu beginnen, <Hexenmeister/Hexenmeisterin>. Aber passt gut auf, denn die heutige Beschwörung ist viel schwerer als alle, die Ihr kennt oder bisher miterlebt habt.\n\nSeid Ihr also bereit?", sourceObjective = "Schließt das Beschwörungsritual mit dem Rat der Schwarzen Ernte im Kreis der Mächte in Dalaran ab.", completion = "Calydus tut leid, dass wir Eure Freunde nicht gerettet haben, aber vielleicht überleben sie, wenn wir uns beeilen.\n\nJagganoth wird sie foltern, aber er lässt seine Opfer am Leben... meistens.", sourceObjectiveStatus = "unverified-source-field" }
quests[40730] = { id = 40730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umverteilung", description = "Ihr denkt Euch wahrscheinlich, ich müsste den Wein einfach nur ausliefern.\n\n<Deline schmunzelt.>\n\nWenn es so leicht wäre, wären seine Leute nicht am Verhungern.\n\n<Ihr Gesichtsausdruck wird todernst.>\n\nDiese... sagen wir einfach \"Loyalisten\"... genießen den Überfluss. Sie tanzen nach der Pfeife der Magistrix und haben alles, was sie brauchen.\n\nEs gibt keine Arkweinknappheit. Die Magistrix hat sie künstlich erzeugt, um uns bei der Stange zu halten.\n\nEin paar Flaschen werden sie nicht vermissen, denn sie haben reichlich.\n\nDurchsucht den Platz und bringt so viele zurück, wie Ihr nur tragen könnt.", sourceObjective = "Beschafft 20 Flaschen Arkwein.", progress = "Habt Ihr genug gefunden?", completion = "Ich werde dafür sorgen, dass unser Freund das sicher erhält. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[40731] = { id = 40731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz der Schreckensnarbe", description = "<Freund/Freundin> hat das Artefakt?! Jetzt hat Jagganoth keine Chance mehr!\n\nSchnell, Ihr müsst sofort zurück zur Schreckensnarbe! Vielleicht könnt Ihr Eure Freunde noch vor Jagganoths Rache retten.\n\nWenn Ihr das Herz des Oberanführers an Euch bringt, wird seine Armee Euren Befehlen gehorchen!", sourceObjective = "Besiegt Jagganoth und bringt sein Herz zum Herrschaftssitz des Oberanführers in der Schreckensnarbe.", completion = "Der grausame Jagganoth ist besiegt!\n\nFreund ist neuer Oberanführer der Schreckensnarbe!\n\nDies ist jetzt Euer neues Zuhause. Ihr herrscht über die Schreckensnarbe und könnt kommen und gehen, wie es Euch gefällt!", sourceObjectiveStatus = "unverified-source-field" }
