quests[40739] = { id = 40739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Reaves Thermal Anvil Module" }
quests[40740] = { id = 40740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Toten und die Verdammten", description = "<Erneut berührt ein mächtiger Geist Eure Gedanken.>\n\nGorelix der Fleischreißer ist ein besonders monströser Dämon. Dieser Schlächter tausender Welten hat schon unzählige Völker eigenhändig mit seiner Axt, dem Schlund der Verdammten, ausgelöscht.\n\nEin Kampftrupp der Schwarzen Klinge hat sich aufgemacht, um ihn auszuschalten, aber wir haben nie wieder von ihnen gehört. Ihr werdet erledigen, was ihnen nicht gelungen ist.\n\nAber Ihr werdet nicht allein gehen. Ich habe Baron Splitter vorausgeschickt, um Euch zu unterstützen.\n\nZieht los, erledigt Gorelix und erbeutet den Schlund der Verdammten.", sourceObjective = "Reist nach Dalaran und fliegt auf Zeomus zur Dunkelsteininsel. Durchschreitet dort das Dämonenportal, um Baron Splitter zu finden und mit ihm zusammen den Schlund der Verdammten zu erbeuten.", completion = "Diese Axt jagt mir Schauer über den Rücken, {name}. Sie ist unbestreitbar sehr mächtig, aber sie strahlt auch eine niemals stillbare Gier aus.\n\nWir werden sie nutzen, weil wir sie brauchen, um diesen Krieg zu gewinnen. Aber an Euer Stelle wäre ich dennoch sehr vorsichtig mit dieser Waffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[40743] = { id = 40743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 011" }
quests[40744] = { id = 40744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uraltes Rezept", description = "Suramar ist... oder war, vielmehr... der Traum eines Gelehrten.\n\nWir haben dort alles erforscht: Alchemie, Kunst, die Natur der Magie an sich. Wie konnten wir nur so töricht sein, sie hereinzulassen?\n\nAch, ich träume wieder vor mich hin, obwohl so viel zu tun ist. Meine Arbeit erfordert einige recht schwer zu beschaffende Zutaten, {race}. Würdet Ihr mir wohl helfen, sie zu besorgen?\n\nIch werde einige Harpyienkrallen benötigen. Wenn man sie zu Pulver zermahlt, sind sie ein starkes Reagenz.", sourceObjective = "Sammelt 6 Harpyienkrallen.", progress = "Habt ihr die Sachen, die ich brauche, {race}? Uns bleibt nicht viel Zeit.", completion = "Das sollten mehr als genug sein. Krallenpulver verliert seine mächtigen Eigenschaften recht schnell, also müssen wir uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40745] = { id = 40745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schichtwechsel", description = "Eine bessere Chance zur Rettung von Verenes Tochter werden wir nicht bekommen.\n\nIch sage Euch, wie es ablaufen wird.\n\nIhr wartet hier, bis die Wache auf dem Weg zur nächsten Schicht an Euch vorbeikommt. Seht Euch nach etwas um, worin Ihr Euch verstecken könnt.\n\n<Silgryn markiert den Ort auf Eurer Karte.>\n\nIhr könnt die Wache an ihrer strahlend roten Rüstung erkennen.\n\nBleibt an ihr dran, aber lasst Euch dabei nicht sehen. Möglicherweise müsst Ihr die Wache töten, wenn Ihr Euer Ziel erreicht.\n\nDer Name des Kindes ist Korine. Viel Glück.", sourceObjective = "Versteckt Euch im Korb und wartet, bis die Wache erscheint. Folgt der Wache an ihr Ziel.", progress = "W-Wer seid Ihr?", completion = "I-Ich dachte... sie würden mich... *schnief*", sourceObjectiveStatus = "unverified-source-field" }
quests[40746] = { id = 40746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter die Leute mischen", description = "Es wird Zeit, dass Ihr die Stadt selbst kennenlernt, {name}.\n\nIch schicke Euch zu meinem treuen Freund Vanthir. Ich hoffe, Ihr erinnert Euch an ihn. Er erinnert sich jedenfalls noch sehr gut an Euch.\n\nIch kann Euch nicht begleiten, aber ich muss Euch dringend darauf hinweisen, dass die Tarnung, die ich Euch überlassen habe, nicht undurchschaubar ist. Gebt auf Euch acht und lasst Euch nicht zu lange anstarren.\n\nAuf Wiedersehen.", sourceObjective = "Sucht Vanthir in Suramar auf.", completion = "Es freut mich, dass Ihr gekommen seid. Wir können Eure Hilfe wirklich gut brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40747] = { id = 40747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die hohe Kunst der Telemantie", description = "Ich hatte keine Zeit, mein Werkzeug einzusammeln, bevor ich aus dem Palast geflohen bin. Ich bin hier, um etwas davon zu retten.\n\nDiese alte Werkstatt besteht aus mehreren Räumen, die durch Teleportationsplattformen verbunden sind.\n\nElisandes Schläger suchen den Komplex schon nach mir ab, doch von hier aus kann ich das Teleportationsnetzwerk manipulieren und sie im Kreis laufen lassen.\n\nGeht Ihr hinein. Ich werde ein Auge auf Eure Position haben und dafür sorgen, dass die Teleporter für Euch normal funktionieren.\n\nFindet diese zwei Teile und bringt sie mir!", sourceObjective = "Sammelt den verwitterten telemantischen Signalgeber und die gesprungene Warpmuffe in Oculeths Werkstatt ein.", progress = "Wir müssen unbedingt die Instrumente hier bergen, wenn ich ein Teleportationsnetzwerk für Thalyssra entwickeln soll.", completion = "Die sind in nicht besonders gutem Zustand, werden ihren Zweck aber erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40748] = { id = 40748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Netzwerksicherheit", description = "Wir müssen das Gebäude abriegeln. Sonst könnten meine geschätzten Kollegen aus dem Palast meine Geheimnisse entdecken, was ein Risiko für die Teleporter darstellen würde, die ich Euch und Thalyssra baue.\n\n<Das inaktive Einstimmungsgerät neben Oculeth wird summend aktiv.>\n\nDamit gelangen wir in meine geheime Testkammer unter dem Berg. Von dort aus können wir die Abriegelung einleiten und entkommen!", sourceObjective = "Schließt die Abriegelungssequenz in Oculeths Testkammer ab.", completion = "Haben wir... es geschafft?", sourceObjectiveStatus = "unverified-source-field" }
quests[40749] = { id = 40749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen zur Erinnerung", description = "Die Blume liegt ruhig in Eurer Hand und leuchtet schwach.\n\nDiese Art scheint zwar hier in der Umgebung nicht zu wachsen, doch liegen kleine Sträuße auf einigen Grabmälern.\n\nVielleicht wird es weniger düster, wenn Ihr ein paar Blumen auf die verbleibenden Gräber legt.", sourceObjective = "Platziert 4 Sträuße Mondlilien.", sourceObjectiveStatus = "unverified-source-field" }
quests[40751] = { id = 40751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 020 - Olivian Rise" }
quests[40752] = { id = 40752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 021 - Oracle" }
quests[40753] = { id = 40753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blingtron 6000", sourceObjective = "Ich bin darauf programmiert, Geschenke zu verteilen, während Ihr meiner Beobachtung nach darauf programmiert seid, Geschenke zu empfangen.\n\nSollen wir eine für beide Seiten vorteilhafte Transaktion einleiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[40755] = { id = 40755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckt unter Stapeln", description = "Magnis Information war sehr aufschlussreich. Es ist immer gut, jemanden zu kennen, der einen Draht zu einem Titanen hat.\n\nUnd jetzt müssen wir nach Karazhan. Ihr wisst ja sicher selbst, wie gefährlich es dort sein kann. Der Turm ist mit unzähligen Schichten von Zaubern durchwoben und das Zusammenspiel der Gewalten kann mitunter etwas... unberechenbar sein. Also passt auf Euch auf.\n\nIch werde mich Euch drinnen anschließen. Ich brauche nur einen Moment, um... meine Gedanken zu ordnen. Dieser Ort birgt viele Erinnerungen für mich.", sourceObjective = "Betretet Karazhan und sucht zusammen mit Khadgar nach dem Wissen um die Säulen der Schöpfung.", progress = "Habt Ihr etwas für mich?", completion = "Nicht lange, nachdem Ihr fort wart, griff die erste Welle der Dämonen an. Wir können sie zurückhalten... zumindest vorerst.\n\nIch werde diesen Folianten sicher verwahren, bis wir Gelegenheit haben, ihn gründlich zu studieren.\n\nGute Arbeit da drinnen. Ich würde die Bibliothek von Karazhan eines Tages gern selbst in Augenschein nehmen. Zumindest glaube ich das...", sourceObjectiveStatus = "unverified-source-field" }
quests[40759] = { id = 40759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 012" }
quests[40760] = { id = 40760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Als ob hier noch nicht genug Aufruhr herrscht, sind jetzt auch noch Gäste eingetroffen... die Illidari.\n\nDiese Dämonenjäger waren seit dem Fall ihres Meisters im Schwarzen Tempel gefangen. Wenn die Wächterinnen sie freigelassen haben, kann das nur bedeuten, dass wir in höchster Gefahr schweben.\n\nDie Anführerin ihrer Abordnung, Allari \"die Seelenfresserin\", behauptet, dass Orgrimmar sich einer versteckten Bedrohung gegenübersieht. Ich habe ihnen gestattet, ein Lager innerhalb der Stadt aufzuschlagen... für den Moment.\n\nIhr werdet auf der Stelle mit ihr sprechen. Findet heraus, ob an dieser Bedrohung etwas Wahres ist.", sourceObjective = "Sprecht mit Allari der Seelenfresserin.", completion = "<Allari runzelt beim Sprechen die Stirn.>\n\nIhr habt doch nicht etwa geglaubt, die Anführer der Horde könnten sich an einem Ort sammeln und würden dabei nicht von der Brennenden Legion bemerkt werden?", sourceObjectiveStatus = "unverified-source-field" }
quests[40761] = { id = 40761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geflüster von Oronaar", description = "Astrale, die Leere, ein dunkler Naaru... Ich spüre, dass sie alle miteinander verbunden sind.\n\nIch habe die Ruinen da unten erkundet, während Ihr und Velen auf der Suche nach der Krone wart. Es gibt Überlebende, {name}.\n\nDie Zerschlagenen streifen durch die zerstörte Gebäudeansammlung im Westen... Ich verstehe nicht viel von dem, was sie sagen, aber ich vermute, dass ihr Verstand kontrolliert wird.\n\nWenn die Leere dafür verantwortlich ist, werden wir dort unsere Untersuchungen beginnen müssen.\n\nIn der Zwischenzeit werde ich meine eigenen Forschungen vorantreiben.", sourceObjective = "Untersucht die Ruinen von Oronaar.", completion = "Irgendetwas stimmt hier ganz und gar nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40762] = { id = 40762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preis des Fanatismus", description = "Kommandantin Domitille ist die perfekte Verkörperung der Verderbnis der Nachtgeborenen: Sie verachten alle Macht, die nicht die ihre ist, folgen ihrer Großmagistrix mit beinahe schon fanatischer Hingabe und haben nichts anderes als die Vernichtung der Mondwache im Sinn.\n\nBringt ihren Helm als Beweis ihres Ablebens zu Lothrius.", sourceObjective = "Bringt den Helm von Kommandantin Domitille zu Lothrius Mondrufer.\n\nBereitgestellter Gegenstand:", completion = "Ich hatte mich schon gewundert, warum es so still um sie geworden ist... Für mich ist es nur ein kleiner Trost, aber den verbleibenden Truppen der Nachtgeborenen habt Ihr damit einen herben Schlag versetzt. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40763] = { id = 40763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spontane Umverteilung", description = "In letzter Zeit gab es viele verstörende Änderungen bezüglich unserer wertvollsten Ressource, des Arkweins.\n\nIch gehe davon aus, dass Thalyssra Euch darüber aufgeklärt hat, was passiert, wenn ein Nachtgeborener keinen Zugang zu einer Machtquelle wie dem Arkwein erhält.\n\nSeitdem die Dämonen da sind, gab es Rationierungen. Viele erhalten nicht mehr genug, um sich ausreichend zu nähren.\n\nSchafft mir so viel Arkwein herbei, wie Ihr nur könnt. Ich werde ihn dann den richtigen Leuten zukommen lassen.", sourceObjective = "Sammelt 20 Flaschen Arkwein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40764] = { id = 40764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest for Latosius Challenge 1" }
quests[40765] = { id = 40765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Syrana Tracker" }
quests[40766] = { id = 40766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charfeather" }
