quests[40768] = { id = 40768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - W1 - Intro to Illidari Complete" }
quests[40772] = { id = 40772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 013" }
quests[40773] = { id = 40773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodshard" }
quests[40776] = { id = 40776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kazok'thul", description = "Ein abtrünniger Teufelsjäger namens Kazok'thul versetzt die Azurschwingenrast in Azsuna in Angst und Schrecken.\n\nTeufelsjäger ernähren sich von Arkanenergie, und Kazok'thul hat sich offenbar am Mana der Azurschwingenwelpen in der Nähe gelabt.\n\nReist zur Azurschwingenrast und sprecht mit Ardonu, um den letzten bekannten Aufenthaltsort von Kazok'thul zu erfahren.\n\nTötet den Dämon und kehrt zurück, wenn Eure Mission abgeschlossen ist.", sourceObjective = "Sucht nach Kazok'thul in der Azurschwingenrast und tötet ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[40779] = { id = 40779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir brauchen noch mehr Macht!", description = "Gute Nachrichten, {race}! Ich habe noch eine Kugel der Macht ausfindig gemacht.\n\nZuletzt habe ich sie im Lager der Nachtgeborenen südwestlich von hier gesehen. Ich musste verschwinden, bevor eine Patrouille mich entdeckt hätte, aber für Euch wäre es doch sicher ein Leichtes, oder?", sourceObjective = "Findet die aufgeladene Kugel der Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40781] = { id = 40781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Chosen" }
quests[40783] = { id = 40783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sichel von Elune", description = "Ich habe erfahren, dass Tyrande selbst die Freigabe eines bedeutenden Artefakts genehmigt hat. Die Sichel von Elune soll unserer Sache dienen. Valorn Stillzweig hat zugestimmt, uns die Waffe auszuhändigen, die er als Teil seiner Nachforschungen über die verfluchten Worgen des Dämmerwalds verwahrt hatte.\n\nIch glaube, dass nur bei Euch die Hoffnung besteht, die Macht der Waffe nutzen zu können, ohne der tierischen Wut zu erliegen, die in ihr wogt. Begebt Euch zum Dämmerwald und beschafft die Sichel für den Kampf gegen unsere Feinde!", sourceObjective = "Trefft Euch mit Valorn Stillzweig im Zwielichtshain des Dämmerwalds.", progress = "Der Champion trifft ein. Ich hoffe, Ihr seid auf diese Last vorbereitet.", completion = "Seid gegrüßt, Champion.\n\nSeid Ihr bereit für die Bürde, die Euch erwartet?", sourceObjectiveStatus = "unverified-source-field" }
quests[40784] = { id = 40784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr rechtmäßiger Platz", description = "Auch wenn ich nur wider besseres Wissen Folge leiste, wünscht Tyrande, dass die Sichel von Elune erneut gegen die Bedrohung durch die Legion in den Kampf getragen wird. Immerhin ist es ein leichter Trost, dass die Waffe von einem Bewahrer des Gleichgewichts wie Euch selbst geführt werden wird.\n\nVergesst nicht, dass der letzte Kampf mit der Sichel zu einer großen Katastrophe geführt hat. Ihr müsst aufpassen, dass der in ihr wohnende bestialische Zorn nicht entfesselt wird.\n\nMit diesen Worten überlasse ich Euch nun die Sichel, auf dass Ihr unsere Feinde ihre Wut erfahren lassen werdet. Möge das Licht von Elune Euch behüten.", sourceObjective = "Lasst Euch von Valorn die Sichel von Elune aushändigen.", progress = "Die Sense gehört Euch, {class}.", completion = "Valorn...\n\nDas war... ein Dunkler Reiter!\n\nWie konnte der uns hier im Schutz des Hains erreichen?", sourceObjectiveStatus = "unverified-source-field" }
quests[40785] = { id = 40785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Feind im Dunkeln", description = "Ich kann nicht fassen, dass die Dunklen Reiter uns hier gefunden haben. Schon lange haben sie nach der Sichel gesucht, denn sie begehren all die Artefakte von Azeroth. Wir dachten, im Hain wären wir sicher...\n\nUnd jetzt ist Valorn tot...\n\nIhr müsst <zum Jäger/zur Jägerin> werden, {name}. Sucht die Dunklen Reiter und holt die Sichel zurück. Zuletzt haben wir sie am Anwesen der Dunstmantels im Dämmerwald gesehen. Beginnt dort mit Eurer Suche.\n\nUnd {name}... Lasst für Valorn Gerechtigkeit walten. Der Reiter muss büßen.", sourceObjective = "Beginnt Eure Suche nach der Sichel von Elune beim Anwesen der Dunstmantels im Dämmerwald.", completion = "Also hatte ich recht und Ihr begehrt die Sichel. Um sie zu erhalten, müssen wir etwas vollbringen, das noch kein Bewohner des Dämmerwalds je versucht hat.\n\nWir müssen die Dunklen Reiter jagen.\n\nIch folge ihrer Fährte schon, seit ich bei der Jagd auf den Wolfskult auf sie gestoßen bin. Sie sind ein Schandfleck auf diesem Land und haben kein Anrecht auf die Artefakte, die sie anhäufen.\n\nWenn wir dieses Artefakt zurückholen wollen, müssen wir ihr Versteck finden. Glücklicherweise könnte ich dafür schon den passenden Hinweis haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40786] = { id = 40786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwelende Funke", description = "Bei Eurer ersten Berührung ist er eiskalt, doch plötzlich bricht der Funke ohne Vorwarnung in Flammen aus und erlischt genauso schnell wieder. Währenddessen spielen sich Bilder von Feuer und Drachen vor Eurem geistigen Auge ab, dabei könnt Ihr jedoch ein Gespräch in Orgrimmar hören und der vertraute Anblick kreisrunder Portale erregt Eure Aufmerksamkeit.", sourceObjective = "Bringt den schwelenden zeitverzerrten Funken zu Kiatke in Orgrimmar.", completion = "Gut, ein weiteres dieser lästigen Artefakte. Die Einmischungen in die Zeitströme haben in letzter Zeit zugenommen... oder werden sie das noch?\n\n<Sie seufzt schwer.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40787] = { id = 40787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der schwelende Funke", description = "Bei Eurer ersten Berührung ist er eiskalt, doch plötzlich bricht der Funke ohne Vorwarnung in Flammen aus und erlischt genauso schnell wieder. Währenddessen spielen sich Bilder von Feuer und Drachen vor Eurem geistigen Auge ab, dabei könnt Ihr jedoch ein Gespräch in Sturmwind hören und der vertraute Anblick kreisrunder Portale erregt Eure Aufmerksamkeit.", sourceObjective = "Bringt den schwelenden zeitverzerrten Funken zu Kiatke in Sturmwind.", completion = "Gut, ein weiteres dieser lästigen Artefakte. Die Einmischungen in die Zeitströme haben in letzter Zeit zugenommen... oder werden sie das noch?\n\n<Sie seufzt schwer.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40792] = { id = 40792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verwüsteter Pfad durch die Zeit", description = "Der Stern des Zerstörers bedeckt das Land mit seinem durchdringenden Licht, sodass sich selbst die Geister in die Schatten zurückziehen. Dieser Stern ist wie kein anderer am Himmel. Er offenbart selbst die Schwächen der furchtlosesten Helden. Solange er am Himmel steht, können sich neue Pfade zu fernen Orten oder sogar Zeiten eröffnen. Die Gelehrten sind ratlos, was die Natur dieses Zeichens betrifft, doch das Glück belohnt bekanntlich die Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40793] = { id = 40793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Frage der Planung", description = "Eure Waffe ist stärker als je zuvor. Jetzt ist der perfekte Zeitpunkt, um sie im Kampf gegen die Legion einzusetzen.\n\nMeister Hsu hat einen Befehlstisch auf dem Ausbildungsgelände eingerichtet und Berichte von all unseren Freunden und Verbündeten in ganz Azeroth gesammelt.\n\nWenn Ihr bereit seid, wird er Euch auf den neuesten Stand bringen, <Großmeister/Großmeisterin>.", sourceObjective = "Sprecht mit Meister Hsu.", completion = "Großmeister, ich habe einen kurzen Bericht über alles, was ich über die Verheerten Inseln weiß, zusammengestellt.\n\nIhr werdet ihn sicher interessant finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40794] = { id = 40794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Revanche der Königin", description = "<Diese Art von Informationen sollte man mit anderen teilen. Vielleicht weiß jemand in der Graufangenklave in Dalaran etwas damit anzufangen.>", sourceObjective = "Bringt das Logbuch des Kapitäns zu Leutnant Surtees in der Graufangenklave in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "<Als der Offizier sich ansieht, was Ihr ihm anbietet, leuchten seine Augen auf.>\n\nWisst Ihr eigentlich, was das ist? Ihr habt hier vielleicht die wertvollsten Geheiminformationen der gesamten Kampagne geliefert.\n\nIch werde persönlich dafür sorgen, dass Lord Graumähne sie erhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[40795] = { id = 40795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf beginnt", description = "Die Brennende Legion hat eine Spur der Verwüstung in Azeroth hinterlassen. Wenn wir diesen Krieg beenden wollen, müssen wir ihre Basen auf den Verheerten Inseln angreifen.\n\nIch habe eine Karte der Inseln und eine Liste der dort zu erledigenden Aufgaben zusammengestellt.\n\nWenn Ihr die Karte eingesehen habt, solltet Ihr festlegen, wo wir mit unserem Angriff beginnen wollen.", sourceObjective = "Wählt Euren ersten Angriffspunkt auf den Verheerten Inseln aus.", completion = "Eine ausgezeichnete Wahl, Großmeister.", sourceObjectiveStatus = "unverified-source-field" }
quests[40796] = { id = 40796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Tode nah", description = "Ich h-habe... Fehler gemacht...\n\n<Absolon holt krächzend Luft.>\n\nIch möchte es wiedergutmachen... Ich will leben! Aber der Wahnsinn... das VERDORREN...\n\nIch... entschwinde.\n\n<Absolon starrt Euch hilflos an.>", sourceObjective = "Gebt Absolon 100 uraltes Mana.", progress = "Könnt Ihr mir helfen? Könnt Ihr denn gar nichts tun?", completion = "<Absolon verschlingt sofort das uralte Mana und scheint für kurze Zeit unfähig zu sprechen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40797] = { id = 40797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 014" }
quests[40798] = { id = 40798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung fest umklammert", description = "Eure Freundlichkeit hat mich inspiriert.\n\nIch dachte, ich werde auf ewig zwischen den leeren Hüllen der Verdorrten umherwandern, aber dann lud mich Thalyssra ein.\n\nIch habe beschlossen, hier bei meinem Volk zu bleiben, und gemeinsam werden wir Suramar zurückerobern.\n\nIm Moment habe ich nur eine Bitte.\n\nGebt meiner Frau diesen Brief. Neben anderen Dingen soll sie wissen, dass ich noch lebe.\n\nGebt auch ihr die Hoffnung, die Ihr mir gabt.", sourceObjective = "Überbringt den Brief Absolons Frau Noressa.", progress = "<Noressa schaut Euch misstrauisch an.>", completion = "Absolon... lebt?", sourceObjectiveStatus = "unverified-source-field" }
quests[40803] = { id = 40803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr Hab und Gut" }
quests[40804] = { id = 40804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Li Li Slotted" }
quests[40810] = { id = 40810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Dorion Fed" }
quests[40814] = { id = 40814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kraft zu überleben", description = "Im Kampf gegen die stärksten Krieger der Legion waren wir lange auf Fürst Illidan angewiesen. Viele von uns haben Bedenken geäußert, dass wir es ohne ihn nicht schaffen würden.\n\nAber glücklicherweise haben sich diese Bedenken jetzt erledigt.\n\nWir haben von zwei Paar Klingen erfahren, die noch mächtiger als jene von Fürst Illidan sein sollen und die sich zudem auch noch in Reichweite befinden.\n\nWenn wir schnell genug handeln, sollten wir ein Paar davon erbeuten können, ohne die Bewegungen der Legion aus den Augen zu verlieren.\n\nIch muss die Entscheidung, welche von ihnen wir uns aneignen wollen, Euch überlassen, {name}.", sourceObjective = "Wählt eine Artefaktwaffe aus, nach der Ihr suchen wollt.", completion = "Eine gute Wahl. Wir dürfen keine Zeit verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[40815] = { id = 40815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von innen heraus", description = "Unsere Dämonenjäger, Kor'vas Blutdorn und Cyana Nachtgleve, sind mit einer kleinen Streitmacht der Illidari nach Faronaar übergesetzt. Ihre Mission war es, die Legion von innen heraus zu schwächen.\n\nIch habe schon eine Weile nichts von ihnen gehört.\n\nEs wäre das Beste, wenn Ihr sie finden und zum Erfolg führen könntet. Einverstanden?", sourceObjective = "Sucht nach Kor'vas Blutdorn auf Faronaar am Triumphposten.", completion = "Oh, Ihr seid es, {name}. Gut, wir haben hier nämlich ein kleines Problem.\n\nTraut Altruis Cyana und mir nicht zu, damit fertigzuwerden? Vielleicht hat er dieses Mal recht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40816] = { id = 40816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kraft zu überleben", description = "Illidan und ich mögen unterschiedlicher Meinung gewesen sein, aber er war unbestreitbar mächtig. Er persönlich hat einige der stärksten Soldaten der Legion ausgeschaltet.\n\nAber das spielt jetzt keine Rolle mehr.\n\nEs gibt zwei Paar Klingen, die man vielleicht noch in die Hände bekommen kann und die angeblich noch mächtiger sind als jene von Illidan.\n\nLeider sind wir zu wenige, um uns auf die Suche nach ihnen zu begeben und gleichzeitig die Legion im Auge behalten zu können. Und ich befürchte, dass diese Gelegenheit nur von kurzer Dauer sein wird.\n\nAls <ranghöchster/ranghöchste> Illidari fällt diese Entscheidung Euch zu.", sourceObjective = "Wählt eine Artefaktwaffe aus, nach der Ihr suchen wollt.", completion = "Ihr müsst umgehend handeln. Die Zeit ist knapp.", sourceObjectiveStatus = "unverified-source-field" }
quests[40817] = { id = 40817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twinblades of the Deceiver Chosen" }
quests[40818] = { id = 40818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aldrachi Warblades Chosen" }
quests[40819] = { id = 40819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abmachungen treffen", description = "Erinnert Ihr Euch an Varedis, {name}? Er war einst unser Hauptausbilder, aber er fiel vor Jahren zusammen mit dem Schwarzen Tempel.\n\nZumindest dachten wir das.\n\nKor'vas hat diesen Verräter in den Reihen der Legion ausgemacht. Er schwingt ihr vollkommen unbekannte, mit Macht durchtränkte Gleven.\n\nDie Kirin Tor haben einen Eredarfürsten in der Violetten Festung eingekerkert, der wissen müsste, wo sich Varedis' Festung befindet. Der Gefängniswärter hat sich bereit erklärt, uns Zugang zu ihm zu gewähren.\n\nZeit, ein bisschen Überzeugungsarbeit zu leisten.", sourceObjective = "Trefft Euch mit Kayn Sonnenzorn vor der Violetten Festung.", completion = "Ich kann diese Magier und ihresgleichen nicht leiden, aber sie sind notwendige Verbündete.", sourceObjectiveStatus = "unverified-source-field" }
quests[40820] = { id = 40820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 015" }
quests[40821] = { id = 40821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überwältigende Macht", description = "Ihr habt jetzt die Befehlsgewalt über Jagganoths Diener, <Oberanführer/Oberanführerin>, aber an diesem Ort lassen sich noch ganz andere Kräfte nutzen!\n\nHier am Herrschaftssitz des Oberanführers findet Ihr einen speziellen Altar, der aus dem Blut des Grubenlords geschaffen und mit seiner Kraft erfüllt wurde. Diese Kraft könnt Ihr auf Eure neue Waffe übertragen.\n\nTretet an den Altar heran, <Oberanführer/Oberanführerin>, und ergreift Besitz von Jagganoths Kraft!", sourceObjective = "Verwendet den Teufelsblutaltar, um Euren ersten Artefaktbonus freizuschalten.", completion = "Ja, Eure Waffe wird stärker!\n\nAber Freund kann jetzt nicht ruhen, denn es wartet bereits eine neue Gefahr!", sourceObjectiveStatus = "unverified-source-field" }
quests[40823] = { id = 40823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederaufbau des Rates", description = "<Freund/Freundin> scheint die Aufmerksamkeit von Mephistroth erregt zu haben. Das sind schlechte Neuigkeiten, denn der Schreckenslord wird Rache für seinen General nehmen wollen.\n\nIhr braucht mehr als die Schreckensnarbe, um gegen ihn zu bestehen. Ihr benötigt mächtige Hexenmeister, wie jene, die gefangen genommen wurden.\n\nCalydus glaubt, der Orc ist noch in der Grube, wo Ihr selbst angekettet wart. Ihr müsst ihn wiederbeleben und den Rat wieder aufbauen!", sourceObjective = "Lasst Ritssyn Flammengroll in der Schreckensnarbe wiederauferstehen.", progress = "Ich werde nicht ruhen, bis der Rat wiederaufgebaut wurde.", completion = "Ich kann meinen eigenen Augen kaum glauben. Ich hätte nie gedacht, dass der Rat einen {class} hervorbringt, der eine ganze Armee von Dämonen unterwerfen kann. \n\nIch hoffe, dass diese Macht groß genug ist, den Krieg zu unseren Gunsten zu entscheiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40824] = { id = 40824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pfad der Schreckensnarbe", description = "Offensichtlich scheint Ihr vollbringen zu können, woran der Rat gescheitert ist. Die Schreckensnarbe wird einen guten Verbündeten abgeben, aber das wird vielleicht nicht reichen.\n\nZunächst einmal müssen wir uns neu sammeln. Ich werde Agenten aussenden, um nach den gefangenen Ratsmitgliedern zu suchen und weitere Hexenmeister zu rekrutieren, die uns beistehen könnten.\n\nTrefft mich am Wahrsagebecken. Dort werden wir unsere nächsten Schritte planen.", sourceObjective = "Verwendet die Schlachtpläne der Schreckensnarbe, um Eure erste Zone auszuwählen.", completion = "Damit steht der Plan fest und die Aktionen laufen an.", sourceObjectiveStatus = "unverified-source-field" }
quests[40829] = { id = 40829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Draenor 6.2 - Raid Finder - 1st" }
quests[40830] = { id = 40830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nahe genug", description = "<Oculeths Augen wirken trübe. Seine Stimme zittert.>\n\nSind wir... schon in der Nähe?\n\nSo hungrig...", sourceObjective = "Tragt Großtelemant Oculeth zu Thalyssra in Shal'Aran.", progress = "Wo ist Oculeth?", completion = "Danke, dass Ihr Euch um Oculeth gekümmert habt. Er wird uns eine unschätzbare Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40832] = { id = 40832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Ungekrönten", description = "Meine Auftraggeber haben mir strikte Anweisung gegeben, Euch dieses Schreiben so schnell wie möglich zu überbringen.\n\nDer Inhalt ist streng geheim und allein Euch vorbehalten.\n\nViel Glück.", sourceObjective = "Lest den versiegelten Brief und folgt den darin enthaltenen Anweisungen.", completion = "Euer Ruf eilt Euch voraus, {name}.\n\nEntschuldigt bitte die Heimlichtuerei. Wir durften einfach nicht riskieren, dass jemand anderes uns hier findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40834] = { id = 40834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Spuren des Fluchs", description = "Bei meiner letzten Konfrontation mit Euren Feinden konnte ich einen Blick in ihre Vergangenheit erhaschen. Dank des Segens, den mir der Umhang der Reinheit gewährte, sah ich, wer die Dunklen Reiter früher waren.\n\nKommt mit mir zu Aridens Lager am Gebirgspass der Totenwinde. Ich werde Euch auf dem Weg alles Wichtige erklären.", sourceObjective = "Begleitet Revil Kost vom Anwesen der Dunstmantels im Dämmerwald zu Aridens Lager am Gebirgspass der Totenwinde.", completion = "Es ist seltsam, dass die Dunklen Reiter uns nicht hierher gefolgt sind. Aber ich nehme jeden Vorteil, den ich kriegen kann.\n\nIch glaube, dass hier irgendwo der Schlüssel zum Aufenthaltsort der Dunklen Reiter verborgen liegt. Lasst uns mit der Suche beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40835] = { id = 40835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberührte Zeugen", description = "Hier hatte der Händler Ariden sein Lager aufgeschlagen, als er einst versuchte, seine dubiosen Waren dem Zauberer Medivh zu verkaufen. Seltsamerweise ist es über all diese Zeit hinweg relativ unberührt geblieben. Deswegen glaube ich, dass immer noch eine Verbindung zum vormaligen Besitzer bestehen könnte.\n\nHelft mir, das Lager zu durchsuchen. Vielleicht finden wir hier etwas, das uns zu den Dunklen Reitern führt.", sourceObjective = "Sucht Aridens Lager nach Hinweisen auf den Aufenthaltsort der Dunklen Reiter ab.", completion = "Das dunkle Energie verströmende Tagebuch scheint Ariden zu gehören und seine Zeit am Gebirgspass der Totenwinde zu beschreiben. Ein Eintrag ist besonders auffällig:\n\n\"In letzter Zeit sind die Nachtheuler unruhig geworden und es verbreiten sich Gerüchte, dass sich die Sichel von Elune nicht mehr in Darnassus befindet. Sie scheint sich zu nähern, denn die {race} fühlen sich zu ihr hingezogen. Ich muss ihnen einfach nur folgen.\n\nDiese verfluchten Nachtelfen denken, die Waffe wäre bei ihnen sicher verwahrt. Schon bald werden sie begreifen, wie sehr sie sich irren.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[40837] = { id = 40837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd der Totenwinde", description = "Die Nachtheuler! Wenn sie sich am Gebirgspass der Totenwinde befinden, werden sie ebenfalls nach der Sichel suchen.\n\nWir sollten uns trennen und sie verfolgen. Mal schauen, wohin die Spur uns führen wird...", sourceObjective = "Folgt der Spur der Worgen der Nachtheuler.", completion = "Die {race} fühlen sich wohl zu den Katakomben unterhalb von Karazhan hingezogen.\n\nKönnte dort etwa...", sourceObjectiveStatus = "unverified-source-field" }
quests[40838] = { id = 40838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunklen Reiter", description = "Dieses Kanalisationsgitter führt zu den Katakomben unterhalb von Karazhan. Ich habe ihm nie große Beachtung geschenkt, aber das scheint genau der Ort zu sein, zu dem die Nachtheuler sich hingezogen fühlen.\n\nVielleicht haben sich die Dunklen Reiter ja die ganze Zeit direkt unter unseren Füßen aufgehalten! Kommt, lasst uns schauen, wo uns das hinführt.", sourceObjective = "Besiegt die Dunklen Reiter und beansprucht die Sichel von Elune für Euch.", progress = "Es ist vollbracht.", completion = "Heute haben wir den Dunklen Reitern einen schweren Schlag versetzt und einen Sieg für die Bewohner des Dämmerwalds errungen.\n\nSie stehen genauso in Eurer Schuld wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[40839] = { id = 40839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schatten", description = "Ihr schreitet durch die Hallen der Ungekrönten. Wir sind die Königstöter. Wir sind jene, die ganze Imperien zu Fall bringen. Wir sind die ungesehenen Klingen, welche die wahre Geschichte dieser Welt verfassen.\n\nVor Euch sitzen die Schatten: der Rat, der die Klingen der Ungekrönten nach seinen Interessen führt.\n\nIhr seid hier, damit wir Euch ein Angebot unterbreiten können. Nehmt den Platz des letzten Schattens ein und helft uns dabei, die Ungekrönten zu leiten.\n\nWas meint Ihr?", sourceObjective = "Nehmt Euren Platz im Rat der Schatten ein.", progress = "Die Entscheidung liegt bei Euch, {name}.", completion = "Willkommen bei den Ungekrönten, Schatten {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40840] = { id = 40840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine würdige Klinge", description = "Wir haben schon seit geraumer Zeit nach jemanden gesucht, der außerhalb dieser Mauern tätig werden kann.\n\nUnd Ihr seid das Ergebnis dieser Suche, {name}. Ihr werdet die Klinge in der Finsternis sein, die unsere Feinde zu Fall bringt.\n\nUm dies zu erreichen, braucht Ihr Waffen, mit denen Ihr die besten Kämpfer der Legion bezwingen könnt.\n\nGraumähne, Tethys und Valeera haben alle ihre eigenen Pläne, wie wir Waffen finden können, die dieser Aufgabe gerecht werden. Ihr solltet alle drei anhören, bevor Ihr eine Entscheidung fällt.", sourceObjective = "Wählt eine Waffe aus, nach der Ihr suchen wollt.", completion = "Eine gute Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[40842] = { id = 40842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kingslayers Chosen" }
quests[40843] = { id = 40843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadblades Chosen" }
quests[40844] = { id = 40844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fangs of the Devourer Chosen" }
quests[40847] = { id = 40847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine freundliche Abmachung", description = "Ik möcht' Euch een Angebot machen.\n\nSchreckensadmiralin Eliza hett en Klingenpaar, dat se zur Geißel der Südlichen Meere maakt hett. Se hett bovendeem een miener besten Pötte stohlen: de Ende des Horizonts. Jetzt ankert se gerade anner Küste vor Azsuna.\n\nWenn Ihr mi helfen könnt, dat Schiff zurückzuholen, dürft Ihr ihre verfluchten Kling' behalten.\n\nTrefft mi eenfach an Bord de Purpurschleier, so Ihr mien Angebot annehmt. Se befindet sük am Dock von Beutebucht... wat nu ok ordentlich Gold kostet.", sourceObjective = "Trefft Euch mit Flottenadmiral Tethys auf der Purpurschleier in Beutebucht.", completion = "Ha! Ik wusste doch, dat Ihr kommt!", sourceObjectiveStatus = "unverified-source-field" }
quests[40849] = { id = 40849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schreckensklingen", description = "Bis zu Elizas Position kann ik Eure sichere Reise gewährleisten, doch wenn wi erst maal dort sünd... Nun jaa, Ihr wisst genauso good wie ik, dass dat keine Garantie gifft.\n\nDer Plan is ganz eenfach. Wi bringen die Purpurschleier so nah ran, wie dat geiht, ohne gesehen zu werden, und gahn dort von Bord.\n\nWenn wi die Küste erreicht hebben, begeben wi uns an Bord de Ende des Horizonts, bestechen die Mannschaft zu meutern und jagen dann Eliza und ihre legendären Kling'.\n\nSeggt eenfach Bescheid, sobald Ihr bereit seid.", sourceObjective = "Erobert die Ende des Horizonts und besorgt Euch die Schreckensklingen.", completion = "Ihr hebbt hüüt goode Arbeit geleistet, mien Jung.", sourceObjectiveStatus = "unverified-source-field" }
quests[40850] = { id = 40850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene von Graustein" }
quests[40853] = { id = 40853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[40854] = { id = 40854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unzählige Möglichkeiten", description = "Also, wo Ihr schon mal hier unten seid: Ich habe da etwas, das Euch interessieren könnte.\n\n<Filgo deutet auf einen ausgebrannten Häscher hinter ihm.>\n\nDas Ding habe ich in Azsuna gefunden. Es lag einfach so am Strand rum. Ich wette, dass man den mit ein bisschen Glück und Ingenieursgeschick wieder zum Laufen bringen kann.\n\nVielleicht kann man ihn sogar gegen die Legion einsetzen. Teufel mit Teufel bekämpfen, sozusagen!", sourceObjective = "Nehmt den ausgebrannten Teufelshäscher mit zu Didi Biegezange in Dalaran.", progress = "Wollt Ihr irgendetwas reparieren lassen?", completion = "Wie seid Ihr denn an den rangekommen?!\n\n<Didi untersucht den ausgebrannten Häscher.>\n\nIst Euch klar, was wir damit alles anstellen können? Wir könnten unseren eigenen persönlichen Teufelshäscher daraus machen!\n\nDamit können wir unsere Feinde vernichtend schlagen!\n\nWir könnten unsere Wissenschaft und Technologie enorm voranbringen!\n\nWir könnten uns Getränke von ihm servieren lassen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40855] = { id = 40855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Mann in Azsuna", description = "Du lieber Himmel! Da fehlen aber noch eine MENGE Teile.\n\nWollt Ihr Euch nicht auf die Jagd nach ein paar Getriebeteilen oder so machen, während ich schon einmal an diesem Grundgerüst hier herumbastele?\n\nEin Kollege von uns in Azsuna könnte vielleicht behilflich sein. Sein Name ist Flintlocke.\n\nWenn er Teile zusammensucht, kann er zumindest keinen Ärger machen. Aber lasst ihn bloß nicht irgendetwas BAUEN!", sourceObjective = "Sucht Fargo Flintlocke in Azsuna in der Nähe des Teufelsfeuervorstoßes.", completion = "Pst, {class}! Hier ist alles voll von diesen Dämonenbiestern.\n\nDidi hat Euch also geschickt, ja? Wie geht's der Kleinen denn?\n\nWenn Ihr nach Dämonenteilen sucht, kann ich Euch sicherlich weiterhelfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40856] = { id = 40856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das wird teuer", description = "Wenn Ihr Dämonenteile braucht, seid Ihr hier genau richtig. Hier wimmelt es nur so von diesen Teufelstypen!\n\nDie besten Karten habt Ihr wohl in der Nähe der Portale, gleich südöstlich von hier.", sourceObjective = "Sammelt einen Arm und ein Bein eines Teufelshäschers innerhalb des Teufelsfeuervorstoßes ein.", progress = "Habt Ihr schon gefunden, was Ihr sucht?", completion = "Was genau bastelt Ihr und Didi da eigentlich zusammen?\n\nEtwas Großes? Gefährliches? Explosives?\n\nDann will ich auch mitmachen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40857] = { id = 40857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teil um Teil", description = "So viele Artefakte zu katalogisieren und nie genug Zeit.\n\nSchön, Euch wiederzusehen, {name}. Brann Bronzebart und die Forscherliga sind gerade in Sturmheim und könnten Eure Hilfe bei der Suche nach einem uralten Titanenrelikt brauchen.\n\nBrann wird Euch alles erklären, wenn Ihr Euch bei ihm meldet.", sourceObjective = "Sucht Brann Bronzebart in Sturmheim auf.", completion = "Oh, sehr gut, noch jemand, der helfen will. Das wird eine große Sache, {name}. Ich weiß es einfach!", sourceObjectiveStatus = "unverified-source-field" }
quests[40858] = { id = 40858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fehlende Stücke", description = "Ihr scheint alles zu haben, was Ihr braucht. Kehrt jetzt mit den Sachen zu Didi zurück. Und gebt ihr einen ordentlichen Klaps auf den Rücken von mir, ja?", sourceObjective = "Kehrt zu Didi Biegezange in Dalaran zurück.", completion = "<Ihr gebt Didi einen ordentlichen Klaps auf den Rücken.>\n\nUff! Das ist bestimmt ein Gruß von Flintlocke, nicht wahr?\n\nMal sehen, was Ihr mir mitgebracht habt! Oh, gut, damit können wir etwas anfangen.\n\nIch werde gleich mit den Reparaturen beginnen. Und dabei verwende ich meine neue Erfindung: den Automatikhammer.\n\nHier sind die Abschriften der Baupläne, falls Ihr auch mal einen herstellen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40859] = { id = 40859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schrei: Kopfkanonen!", description = "Wurfhammer hat doch jede Menge Schießeisen auf Lager, nicht wahr? Super! Das hat mich nämlich auf 'ne Idee gebracht: Können wir uns die nicht auf den Kopf setzen?\n\nLasst es mich erklären!\n\nEure Hände sind doch schon mit Euren Waffen beschäftigt, aber was macht Ihr mit Eurem Kopf? Ihr nutzt ihn nur zum GLOTZEN. Mein Plan lautet also, ihn zu bewaffnen!\n\nUnd Ihr seid <der Glücksknabe, der/die Glücksmaid> die; das austesten darf. Setzt das hier auf. Und jetzt zieht los und erlegt ein paar teufelsverderbte Kreaturen damit. Gute Jagd!", sourceObjective = "Tötet 10 Teufelsbiester mithilfe von Flintlockes Kopfkanonenprototyp.", completion = "Und? Was hab ich Euch gesagt? DAS ist Ingenieurskunst mit Köpfchen!\n\nHa! Versteht Ihr? Mit Köpfchen?\n\nUnd da Ihr die Tests für mich durchgeführt habt, gebe ich Euch eine Abschrift der Baupläne.", sourceObjectiveStatus = "unverified-source-field" }
quests[40860] = { id = 40860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die Front", description = "{name}, ich möchte, dass Ihr etwas für mich ausliefert.\n\nFlintlocke hat aus Val'sharah gemeldet, dass ihnen dort die Kugeln ausgehen.\n\nIch selbst habe ihn mit genug Munition dort hingeschickt, um die halbe Welt in Stücke zu schießen. Aber Flintlocke scheint Munition zu brauchen wie andere... Luft zum Atmen. Also los, helft ihm aus der Patsche!", sourceObjective = "Bringt die Munitionskiste zu Fargo Flintlocke in Val'sharah.\n\nBereitgestellter Gegenstand:", completion = "Oh, ja! Das ist genau, was wir brauchen! Ich war kurz davor, kleine Tierchen als Wurfgeschosse zu verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40861] = { id = 40861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Visier", description = "Ich habe die meisten Kugeln mithilfe einer kleinen Erfindung von mir abgefeuert, die ich den stationären Kugelspender nenne!\n\nDieses Ding schießt einfach wahllos drauf los, ohne überflüssigen Quatsch wie \"Zielen\" oder \"Nachdenken\".\n\nWir hatten ein paar davon östlich von hier im Einsatz, als ein Schwarm Pflanzen rankenschwingend aus dem Wald hervorbrach.\n\nIch hatte danach keine Zeit, meine Geschütztürme oder zumindest deren Überreste einzusammeln. Könntet Ihr das für mich übernehmen?", sourceObjective = "Bergt 10 Teile eines stationären Kugelspenders in der Gegend um Mondruh.", progress = "Diese fiesen Grünlinge haben meine Spender doch hoffentlich nicht angerührt, oder?", completion = "Oh, meine armen kleinen Kugelspender! Was haben sie euch nur angetan?!\n\nImmerhin haben sie bis zuletzt geschossen. So würde ich mir mein Ende auch wünschen.\n\nHier ist der Bauplan für die Dinger. Stellt sie möglichst nah bei denjenigen auf, die Ihr am wenigsten mögt!", sourceObjectiveStatus = "unverified-source-field" }
quests[40862] = { id = 40862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkrautvernichter", description = "Wenn Ihr in diese Wälder loszieht, braucht Ihr etwas mit richtig Wumms. Diese Pflanzen sind nämlich ganz schön hartnäckig.\n\nIch habe hier spezielle Sprengladungen, mit denen Ihr diese Düngerbiester in tausend Stücke sprengen könnt.\n\nNehmt sie mit und zeigt diesen Pflanzenfratzen, was eine echte Harke ist!", sourceObjective = "Verwendet Flintlockes Schwarzpulverladungen, um 15 schimmernde Oleander zu töten.", completion = "Das sind gute Unkrautvernichter, oder? Haha!\n\nIch hab mir gedacht, dass Ihr wahrscheinlich noch mehr von diesen Sprengladungen wollt, und hab Euch dafür den Bauplan aufgeschrieben.\n\nIch finde, man muss immer bereit sein, diese Pflanzen und Bäume in Schach zu halten, wenn sie aufmüpfig werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[40863] = { id = 40863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Saft", description = "So, ich habe jetzt ein paar Sachen optimiert, indem ich ein paar neue Schrauben und Muttern verbaut und ein neues Gehäuse für den Kraftkern eingesetzt habe.\n\nDas Problem ist nur, dass keine meiner Batterien zu funktionieren scheint. Offensichtlich müssen wir uns eine eigene Lösung einfallen lassen.\n\nIch werde Eure Hilfe brauchen, {name}. Als Erstes sollten wir einen aufgeladenen Edelstein aus dem Juwelierskunstladen die Straße runter ausprobieren.", sourceObjective = "Sucht nach einer geeigneten Energiequelle für Didis Entwurf und bringt sie ihr. Testet dann, ob die neue Batterie auch funktioniert.", progress = "Ich hoffe, es gestaltet sich nicht allzu schwer, eine geeignete Energiequelle zu finden.", completion = "Wir haben es geschafft! Das ist ein voll funktionsfähiger, gemeingefährlich aussehender Teufelshäscher.\n\nFalls ihm jemals die Energie ausgehen sollte, habt Ihr hier den Bauplan für die verwendete Batterie.\n\nSetzt einfach eine neue ein und Ihr seid wieder startklar!\n\nAber sagt mal, wie soll der Hübsche denn heißen? Ich dachte an etwas Bedrohliches... Wie wär's mit \"Reaves\"?", sourceObjectiveStatus = "unverified-source-field" }
quests[40864] = { id = 40864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modulare Modifikationen", description = "Jetzt wo der Hübsche funktioniert, sollten wir ihn mit ein paar tollen Fähigkeiten ausstatten.\n\nBeim Zusammenbau von Reaves habe ich seinem Hauptschaltkreis auch gleich eine Modulschnittstelle hinzugefügt. Dadurch können wir alles hochladen, was wir wollen.\n\nIch werde Euch einen meiner Modulentwürfe beibringen, dann könnt Ihr Reaves damit ausstatten.", sourceObjective = "Entwerft ein Reaves-Modul: Snackautomatmodus. Ruft dann Reaves, um ihn damit auszustatten.", progress = "Ich habe viele Ideen für weitere Anwendungen. Für den Anfang habe ich erst einmal ein paar davon aufgeschrieben.", completion = "Es scheint alles zu laufen wie geplant. Ehrlich gesagt hatte ich fast damit gerechnet, dass etwas in die Luft fliegt.\n\nHier ist der andere Bauplan, den ich für Reaves angefertigt habe. Er basiert auf dem Bauplan für den Automatikhammer, den Ihr schon von mir bekommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40865] = { id = 40865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist keine Raketenwissenschaft", description = "{name}, Ihr müsst mir helfen, Flintlocke erneut aufzuspüren.\n\nIch habe ihn nach Sturmheim geschickt, um Materialien für eine meiner Erfindungen zu sammeln, und er ist schon seit Tagen nicht mehr hier gewesen. Um Flintlocke mache ich mir keine Sorgen, dafür aber um Sturmheim!\n\nVersucht, ihn ausfindig zu machen!", sourceObjective = "Sucht in Sturmheim nach Fargo Flintlocke.", completion = "{name}, was macht Ihr hier? Hobart hat Euch geschickt, oder?\n\nHört zu, ich brauche Eure Hilfe nicht, aber da Ihr Euch schon hierher begeben habt, können wir vielleicht zusammen für etwas Aufregung sorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40866] = { id = 40866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Her mit den Muscheln!", description = "Ich weiß, dass der alte Hobart will, dass ich hier unten diese wertvollen Murlocglasdinger für ihn einsammle, aber ich habe auch meine eigenen Pläne!\n\nIch hab beobachtet, dass die Murlocs so interessant aussehende Muscheln haben, die sich perfekt für meinen neuen Spieldosenentwurf eignen würden.\n\nGeht Ihr voran, ich folge Euch auf dem Fuße.", sourceObjective = "Tötet Murlocs, um 10 ihrer Muscheln für Fargo Flintlocke einzusammeln.", progress = "Ich mach das hier nur noch kurz fertig und komme dann gleich.", completion = "Oh, Ihr seid schon fertig? Ich wollte mich Euch gerade anschließen. Ehrenwort!\n\nAber das hat sich ja jetzt erledigt. Da Ihr all die Muscheln besorgt habt, werde ich Euch wohl eine Kopie des Bauplans überlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40867] = { id = 40867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überzeugungsarbeit", description = "Der alte Hobart wollte, dass ich diese glitzernden Glasschmuckstücke von den Murlocs einsammle, aber diese verdammten Biester wollen sie nicht rausrücken!\n\nIch hab's erst auf die sanfte Tour versucht, aber ich spreche ja ihre Sprache nicht. Also war ich gezwungen, auf sie zu schießen.\n\nVielleicht könnt Ihr ja mal versuchen, ihnen ein paar Schmuckstücke abzunehmen.", sourceObjective = "Sammelt 12 Murlocschmuckstücke in der Gegend um ihre Lager herum.", progress = "Wart Ihr erfolgreich?\n\nHabt Ihr es auch mit Schießen probiert?", completion = "Sieh mal einer an! Ihr habt ihnen die Schmuckstücke tatsächlich abgequatscht! Eines Tages müsst Ihr mir mal ihre Sprache beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40868] = { id = 40868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnibbedischnick-wibbelig-wobbeliges Zeitzeugs", description = "Ich muss hier noch ein paar Sachen fertig machen. Könntet Ihr vielleicht Hobart diese Schmuckstücke bringen?\n\nAußerdem glaube ich, dass er Euch besser leiden kann.", sourceObjective = "Bringt die Murlocschmuckstücke zu Hobart Wurfhammer in Dalaran.", completion = "Da sind die Teile ja! Wurde auch Zeit.\n\n<Hobart geht hinüber zu einer Maschine und beginnt, die Teile einzusetzen, die Ihr ihm gebracht habt.>\n\nFlintlocke hat Euch also damit hergeschickt? Da Ihr die Lauferei erledigt habt, könnt Ihr von mir aus eine Abschrift der Vorlage haben.\n\nEs ist eine neue Art Wurmlochgenerator. Eigens dafür konzipiert, blitzschnell durch Dalaran zu reisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40869] = { id = 40869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer aus den eigenen Reihen", description = "Man soll ja im Leben immer das Beste aus allem machen. In meinem Fall gilt das natürlich für Waffen.\n\nIch baue diese Waffen so um, dass daraus nützliche Werkzeuge entstehen.\n\nMeine neueste Modifikation kann Verbände verschießen! Stellt Euch mal vor, wie Ihr auf dem Schlachtfeld bemerkt, dass Euer Gefährte verwundet wird, und Ihr ihn dann mit der Bandagenflinte beschießt und – ZACK – ist er wieder kampfbereit!\n\nIch muss aber erst einmal testen, ob sie auch sicher ist.", sourceObjective = "Probiert den Prototypen einer Repetierbandagenflinte bei verwundeten Wächtern der Kirin Tor in Dalaran aus. Möglicherweise müsst Ihr die Flinte kalibrieren.", completion = "Gut, dass Ihr die Feuerkraft schließlich regulieren konntet. Schade nur um die ersten paar Ziele...\n\nIch habe die neu spezifizierten Werte auf dem Bauplan eingetragen, damit Ihr eine sichere Version herstellen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40870] = { id = 40870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerwerk vermisst", description = "{name}, diese kleinen Schlingel haben mein ganzes Feuerwerk gestohlen.\n\nHabt Ihr sie vielleicht gesehen? Ich wollte gerade ein neues Reaves-Modul erstellen, als die Kinder hier reingestürzt sind und sich mit meinen Feuerwerkskörpern davongemacht haben.\n\nIch benötige sie aber, um meine Arbeiten abzuschließen. Könntet Ihr sie bitte zurückholen?", sourceObjective = "Holt Didis Feuerwerk von den Kindern in Dalaran zurück.", progress = "Wenn ich diese Blagen in die Finger bekomme...", completion = "<Didi nimmt Euch das Feuerwerk ab und arbeitet weiter an ihrer Werkbank.>\n\nSo, das wäre erledigt!\n\nWenn Ihr das an Eurem Bot anbringt, könnt Ihr das Feuerwerk jederzeit und überall zünden! Explosionen sind natürlich ALLE wunderschön... aber so ein Feuerwerk ist schon etwas ganz Besonderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[40871] = { id = 40871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Flinte ins Korn", description = "Flintlocke hat nach Euch gesucht, {name}. Ich glaube, er braucht noch einmal Eure Hilfe.\n\nIch habe ihn losgeschickt, um unten in Azsuna einige meiner neuen Erfindungen zu testen. Ihr solltet ihn an der Küste westlich von Ozeanus' Bucht finden.", sourceObjective = "Sucht Fargo Flintlocke in Azsuna.", completion = "Oh, da seid Ihr ja, mein Junge. Ich hatte irgendwie gehofft, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40872] = { id = 40872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserläufer", description = "Also, als ich da draußen diesen neuen Flugrucksack für Hobart getestet habe, ist er einfach explodiert und hat mich hierhergeschleudert.\n\nMan kann die ganzen Teile noch da im Wasser sehen.\n\nIch hab zwar noch diese Stiefel, die ich auch für Hobart testen sollte, aber die passen mir nicht richtig.\n\nVielleicht könntet Ihr ja zwei Fliegen mit einer Klappe schlagen und diese Stiefel testen, während Ihr gleichzeitig die Trümmerteile aus dem Wasser holt.\n\nUnd achtet auf die Haie da draußen.", sourceObjective = "Verwendet die Schießschuhe, um über das Wasser zu fegen und dabei 15 Waffenpaketbruchstücke einzusammeln.", completion = "Ah, das ist ja wundervoll, dass Ihr die Teile zurückgebracht habt. Ich dachte schon, ich müsste die Wächterinsel da drüben in die Luft jagen, um die Bucht trockenzulegen.\n\nIhr scheint mit diesen Stiefeln etwas anfangen zu können. Hier ist der Bauplan, wenn Ihr noch ein Paar davon braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40873] = { id = 40873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Pulver trocken halten", description = "So, jetzt haben wir zwar wieder alle Teile des Pakets, aber dafür habe ich kein Schießpulver mehr.\n\nDas ist das Schlimmste, was mir je passiert ist.\n\nAber es gibt noch Hoffnung: Gleich da drüben im Norden gibt es Höhlen voller havarierter Schiffe. Vielleicht haben die Meeresriesen ja auch ein oder zwei Schiffe mit Kanonen zerstört. Und wo Kanonen sind, muss es ja schließlich auch Schießpulver geben.\n\nSucht die Höhlen nach Pulver ab und bringt etwas davon zurück.", sourceObjective = "Sammelt 8 Fässer mit Schießpulver ein und bringt sie zu Fargo in Azsuna.", progress = "Passt auf, dass das Pulver nicht nass wird. Ich möchte keine Ewigkeit darauf warten, bis es trocknet.", completion = "Oh ja, das sollte reichen, mein Junge. Ich hab ein paar Änderungen an den Plänen für das Waffenpaket vorgenommen.\n\nBehaltet Ihr sie besser. Ihr habt ja gesehen, wie gerne Hobarts Erfindungen bei mir in die Luft fliegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40874] = { id = 40874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellvertretende Rache", description = "Wenn Ihr die Höhlen der Meeresriesen aufsucht, dann verpasst diesen schleimigen Naga eine Extratracht Prügel von mir.\n\nSie haben sich nämlich mit meinem Schurkenkumpel davongemacht und da ist natürlich ein wenig Rache angesagt.\n\nIch würde das ja zu gern selbst erledigen, aber der alte Hobart würde mich kreuzigen, wenn ich seinen Kram hier allein lasse.", sourceObjective = "Tötet 10 Sklaventreiber der Hassnattern in Ozeanus' Bucht.", completion = "Oh, ich hätte ja zu gern ihre verdutzten Fischfressen gesehen.\n\nWobei, Fische sehen ja eigentlich immer irgendwie überrascht aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[40875] = { id = 40875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datensicherung", description = "Also, diese dreckigen Naga haben sich meinen kleinen Gnomenfreund Flachping geschnappt, als wir hier ankamen. Er ist weg! Sie haben ihn einfach mit sich in Richtung dieser Bucht geschleppt!\n\nUnd was noch schlimmer ist: Er hatte einen Bauplan für eine meiner besten Erfindungen dabei.\n\nUnd mit \"dabei\" meine ich, dass er den Plan als Tattoo auf dem Kopf trägt. AUS SICHERHEITSGRÜNDEN!\n\nWenn Ihr ihn findet, dann rasiert ihm den Kopf und fertigt schnell eine Abschrift des Bauplans an.", sourceObjective = "Findet Flachping in den Höhlen der Meeresriesen, rasiert seinen Kopf und fertigt eine Abschrift des auf seinem Schädel eintätowierten Bauplans an.", progress = "Der arme Kerl wird wahrscheinlich gerade gefoltert. Widerliche, verdammte Fischfressen!", completion = "Ja, das ist der Bauplan! Hier, behaltet eine Kopie davon, dann habt Ihr auch etwas, was Ihr irgendwo hintätowieren könnt.\n\nVerdammt schade um Flachping. Wisst Ihr, vielleicht hätten wir ihn ja retten sollen. Tja, man kann eben nicht alles auf einmal erledigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40876] = { id = 40876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über Kimme und Korn", description = "So, damit ist meine Arbeit hier getan. Ich fang an zusammenzupacken und mach mich dann auf den Weg zurück nach Dalaran.\n\nKönnt Ihr mir einen Gefallen tun und Hobart erzählen, was hier los war? Vielleicht lasst Ihr die Sache mit dem Explodieren, dem Ertrinken und dem Verschleppen und so aus.\n\nIhr seid <ein echter Freund/eine echte Freundin>, {name}!", sourceObjective = "Kehrt zu Hobart in Dalaran zurück und berichtet ihm von Flintlockes Arbeit.", completion = "Dann haben die Schießschuhe und das Paket also funktioniert? Offensichtlich waren meine Waffenerfindungen doch keine Zeitverschwendung.\n\nDas erinnert mich an Flintlockes Pläne für diese Schutzbrille. Sein Design war alles andere als ausgereift. Das Wort \"Zwergeningenieurskunst\" ist irgendwie ein Widerspruch in sich.\n\nIch habe den Bauplan überarbeitet, damit man nicht so viele Materialien benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40877] = { id = 40877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Finger am Abzug", description = "Um meine neueste Erfindung zu vollenden, benötige ich ein besonderes Relikt, das wir den Runenstein der Vitalität nennen.\n\nOdyn, der König der Hallen der Tapferkeit, soll damit angeblich seinen Konstrukten Leben einhauchen.\n\nDas ist keine einfache Aufgabe, aber ich bitte Euch, Odyn diesen Runenstein abzunehmen und ihn mir zu bringen.", sourceObjective = "Beschafft den Runenstein der Vitalität von Odyn in den Hallen der Tapferkeit.", progress = "Nur gut, dass Ihr es mit einem Gott aufnehmt und nicht ich.", completion = "Lasst uns die Daumen drücken und hoffen, dass es funktioniert, {name}.\n\n\n\nJa! JA! Es lebt, ES LEBT!\n\nJetzt kann ich die Dinger massenhaft als Kinderspielzeug vermarkten!", sourceObjectiveStatus = "unverified-source-field" }
quests[40878] = { id = 40878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Violette Festung: Von der Schippe springen", description = "Hobart hat mir die Kopie eines Bauplans gezeigt, den Ihr gefunden habt, und das hat mich auf die Idee für ein neues Reaves-Modul gebracht.\n\nLeider hatte ich nicht die entsprechenden Materialien, um es auszuprobieren.\n\nKönntet Ihr ein paar Fehlschlagdetektorpylonen für mich herstellen?\n\nUnd ich brauche auch noch einen plasmatischen Laserriegel. So einen findet Ihr in der Violetten Festung.", sourceObjective = "Stellt 2 Fehlschlagdetektorpylonen her. Besorgt dann in der Violetten Festung einen plasmatischen Laserriegel und bringt anschließend alles zu Didi Biegezange in Dalaran.", progress = "Reißt einfach den Riegel von einer der Gefängniszellen ab. Was immer da drin sein wird, ist sicher schon lange tot.", completion = "<Didi nimmt die Pylonen entgegen, tüftelt an ihnen herum und schreibt dann ein paar Notizen nieder.>\n\nJa, das sollte funktionieren!\n\nEin neuer und verbesserter Bauplan für ein Reaves-Modul für Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40879] = { id = 40879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfbotwettbewerb", sourceObjective = "Die Zeit ist gekommen, Euch zu zeigen, was ich für Reaves geplant habe! Ich präsentiere... den gesteuerten Kampfmodus! Klar, die Zutaten sind unfassbar schwer zu finden und niemand kann wirklich sagen, ob es funktioniert, aber hey... So ist die Ingenieurskunst nun mal!\n\nViel Spaß mit dem Bauplan!", sourceObjectiveStatus = "unverified-source-field" }
quests[40880] = { id = 40880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kurzschluss", description = "Wo Ihr doch schon mal hier seid, könntet Ihr doch etwas für mich herausfinden?\n\nIhr wisst doch sicher, was ein Blingtron ist, oder? Nun, ich habe mich umgehört, aber niemand scheint etwas über den Originalbauplan zu wissen. Allerdings ist dabei immer wieder ein Name gefallen:\n\nArea 52.\n\nLust auf eine kleine Exkursion?", sourceObjective = "Sucht nach dem Erfinder des Blingtrons.", completion = "Zwischen den Dokumenten schwebt ein alter, aber noch intakter Bauplan.\n\nIhr seht ihn Euch genau an und erkennt, dass es der Schaltbauplan für den Blingtron ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[40881] = { id = 40881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Öllappen zu Reichtümern", description = "Didi wird sehr an den gefundenen Notizen und dem Schaltplandesign interessiert sein.\n\nIhr solltet so schnell wie möglich zu ihr zurückkehren.", sourceObjective = "Kehrt zu Didi Biegezange in Dalaran zurück und zeigt ihr die Sachen, die Ihr gefunden habt.", completion = "Dieses Schaltplandesign ist genau, was ich brauche, um das Blingtron-Modul für Reaves fertigzustellen.\n\nUnd hier kommt Eure Belohnung, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[40882] = { id = 40882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: Rückschlagdämpfung", description = "{name}, ich hoffe, es freut Euch zu hören, dass ich an einer besseren Version der Brille arbeite, die Flintlocke entworfen hat.\n\nMeine bietet die doppelte Leistung, hat leider aber auch doppelt so viel Rückschlag. Beim Einsatz würde man sich dummerweise das Genick brechen.\n\nAber ich habe schon eine Lösung gefunden. Tief im Zentrum von Suramar ist ein magischer Mechanismus verborgen, der den Rückschlag praktisch aufhebt.\n\nWenn Ihr mir diesen Mechanismus besorgen könnt, sind wir im Geschäft!", sourceObjective = "Geht zum Hof der Sterne und besorgt den arkanen Kompressor für Hobart.", progress = "Diese Elfen hatten wahrscheinlich keine Vorstellung von den quantenmechanischen Anwendungsmöglichkeiten dieses Mechanismus!", completion = "<Hobart nimmt Euch den Mechanismus ab und beginnt mit der Tüftelei an seinem Bauplan.>\n\nJa, ich glaube, das ist der richtige. Gute Arbeit, {name}.\n\nWie üblich überlasse ich Euch eine Abschrift meines Bauplans für Eure persönlichen Zwecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[40883] = { id = 40883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal der Wache", description = "<Thalrenus mustert Euch.>\n\nIhr gehört nicht zu denen.\n\nEinige Stunden, nachdem der Schild über Suramar gefallen war, tauchten die Nachtgeborenen vor unseren Toren auf. Wir hielten sie für Freunde, trotz unserer langen Trennung.\n\nWir haben uns geirrt.\n\nSie strömten in unsere Festung und begannen, uns abzuschlachten. Darauf waren wir nicht vorbereitet. Obwohl wir kämpften, wurden wir geschlagen.\n\nDie Festung ist verloren. Unsere Anführer sind gestorben und ihre Leichen liegen auf den Straßen.\n\nSucht sie und erweist ihnen die letzte Ehre.\n\nHaltet während Eurer Suche Ausschau nach Überlebenden. Helft ihnen, wenn Ihr könnt.", sourceObjective = "Sucht nach den Leichen von Nyellus Sternweber, Galar'thus Flussbaum und Kailea Windfeder und beerdigt sie mit den angemessenen Zeremonien.", progress = "Seid Ihr hier, um gegen die Nachtgeborenen zu kämpfen?", completion = "Ich dachte, die Mondwache könnte alles überstehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[40888] = { id = 40888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hammer of Khaz'goroth Actived" }
quests[40889] = { id = 40889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tidestone of Golganneth Activated" }
quests[40890] = { id = 40890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Tränen von Elune", description = "Die Träne von Elune schwebt mühelos in der Luft und glitzert in einer ätherischen Säule aus Mondlicht.", sourceObjective = "Verwendet den zentralen Teleporter in Dalaran und platziert die Tränen von Elune dann in der Porträtgalerie.", completion = "<Erzmagier Khadgar hat hier einen Platz für die Tränen von Elune und den Rest der Säulen der Schöpfung reserviert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40891] = { id = 40891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aegis of Aggramar Activated" }
quests[40896] = { id = 40896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trauergesang der Häuptlinge" }
